import { CalendarDays, FolderOpen, Share2, Sparkles, TrendingDown, TrendingUp } from "lucide-react";

import { MetricCard } from "@/components/metric-card";
import { Badge } from "@/components/ui/badge";

export function MetricCards() {
  const metrics = [
    {
      description: (
        <span className="flex flex-wrap items-center gap-1.5">
          <Badge>
            <TrendingUp className="size-3" />
            +12.5%
          </Badge>
          <span>frente a las 4 semanas previas</span>
        </span>
      ),
      icon: CalendarDays,
      label: "Publicaciones",
      value: "24",
    },
    {
      description: (
        <span className="flex flex-wrap items-center gap-1.5">
          <Badge>
            <TrendingUp className="size-3" />
            +2
          </Badge>
          <span>conectados en las últimas 4 semanas</span>
        </span>
      ),
      icon: Share2,
      label: "Canales activos",
      value: "6",
    },
    {
      description: (
        <span className="flex flex-wrap items-center gap-1.5">
          <Badge variant="destructive">
            <TrendingDown className="size-3" />
            -8%
          </Badge>
          <span>frente a las 4 semanas previas</span>
        </span>
      ),
      icon: Sparkles,
      label: "Créditos AI usados",
      value: "340",
    },
    {
      description: (
        <span className="flex flex-wrap items-center gap-1.5">
          <Badge>
            <TrendingUp className="size-3" />
            +4.5%
          </Badge>
          <span>frente a las 4 semanas previas</span>
        </span>
      ),
      icon: FolderOpen,
      label: "Archivos nuevos",
      value: "18",
    },
  ];

  return (
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
      {metrics.map((metric) => (
        <MetricCard key={metric.label} {...metric} />
      ))}
    </div>
  );
}

"use client";

import { CartesianGrid, ComposedChart, Line, XAxis, YAxis } from "recharts";

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { type ChartConfig, ChartContainer, ChartTooltip, ChartTooltipContent } from "@/components/ui/chart";

const activitySeries = [
  { day: 1, current: 0, previous: 1 },
  { day: 2, current: 2, previous: 0 },
  { day: 3, current: 1, previous: 1 },
  { day: 4, current: 0, previous: 2 },
  { day: 5, current: 3, previous: 1 },
  { day: 6, current: 1, previous: 0 },
  { day: 7, current: 0, previous: 1 },
  { day: 8, current: 2, previous: 2 },
  { day: 9, current: 1, previous: 0 },
  { day: 10, current: 0, previous: 1 },
  { day: 11, current: 2, previous: 1 },
  { day: 12, current: 3, previous: 0 },
  { day: 13, current: 1, previous: 2 },
  { day: 14, current: 0, previous: 1 },
  { day: 15, current: 1, previous: 0 },
  { day: 16, current: 2, previous: 1 },
  { day: 17, current: 0, previous: 0 },
  { day: 18, current: 1, previous: 2 },
  { day: 19, current: 3, previous: 1 },
  { day: 20, current: 2, previous: 0 },
  { day: 21, current: 0, previous: 1 },
  { day: 22, current: 1, previous: 1 },
  { day: 23, current: 2, previous: 0 },
  { day: 24, current: 1, previous: 2 },
  { day: 25, current: 0, previous: 1 },
  { day: 26, current: 2, previous: 0 },
  { day: 27, current: 1, previous: 1 },
  { day: 28, current: 2, previous: 1 },
];

const chartConfig = {
  current: {
    color: "var(--chart-3)",
    label: "Últimas 4 semanas",
  },
  previous: {
    color: "var(--muted-foreground)",
    label: "Periodo anterior",
  },
} satisfies ChartConfig;

const weeklyTicks = [4, 11, 18, 25];

function formatWeek(value: number) {
  const weekIndex = weeklyTicks.indexOf(value);

  return weekIndex >= 0 ? `Semana ${weekIndex + 1}` : "";
}

export function PublishingActivity() {
  return (
    <Card className="h-full" variant="subtle">
      <CardHeader>
        <CardTitle className="font-normal">Actividad de publicación</CardTitle>
        <CardDescription>Publicaciones por día frente al periodo anterior.</CardDescription>
      </CardHeader>

      <CardContent>
        <ChartContainer config={chartConfig} className="h-68 w-full">
          <ComposedChart data={activitySeries} margin={{ bottom: 0, left: 0, right: 0, top: 0 }}>
            <CartesianGrid vertical={false} />
            <XAxis
              dataKey="day"
              axisLine={false}
              domain={[1, 28]}
              interval={0}
              tickFormatter={formatWeek}
              tickLine={false}
              tickMargin={14}
              ticks={weeklyTicks}
              type="number"
            />
            <YAxis allowDecimals={false} axisLine={false} tickLine={false} tickMargin={10} width={34} />
            <ChartTooltip
              cursor={false}
              content={<ChartTooltipContent className="w-48" labelFormatter={() => "Publicaciones"} />}
            />
            <Line
              dataKey="previous"
              dot={false}
              stroke="var(--color-previous)"
              strokeOpacity={0.65}
              strokeDasharray="4 4"
              strokeWidth={1.75}
              type="linear"
            />
            <Line
              dataKey="current"
              dot={false}
              activeDot={{ r: 4 }}
              stroke="var(--color-current)"
              strokeWidth={2.5}
              type="linear"
            />
          </ComposedChart>
        </ChartContainer>
      </CardContent>
    </Card>
  );
}

"use client";

import { Clock3, FileText, Image, Recycle } from "lucide-react";
import { Bar, BarChart, type BarShapeProps, XAxis, YAxis } from "recharts";

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { type ChartConfig, ChartContainer, ChartTooltip, ChartTooltipContent } from "@/components/ui/chart";

const usageDays = [
  { day: 1, requests: 0 },
  { day: 2, requests: 6 },
  { day: 3, requests: 12 },
  { day: 4, requests: 20 },
  { day: 5, requests: 12 },
  { day: 6, requests: 0 },
  { day: 7, requests: 6 },
  { day: 8, requests: 6 },
  { day: 9, requests: 0 },
  { day: 10, requests: 4 },
  { day: 11, requests: 0 },
  { day: 12, requests: 20 },
  { day: 13, requests: 15 },
  { day: 14, requests: 4 },
  { day: 15, requests: 6 },
  { day: 16, requests: 0 },
  { day: 17, requests: 4 },
  { day: 18, requests: 12 },
  { day: 19, requests: 20 },
  { day: 20, requests: 0 },
  { day: 21, requests: 4 },
  { day: 22, requests: 20 },
  { day: 23, requests: 12 },
  { day: 24, requests: 0 },
  { day: 25, requests: 6 },
  { day: 26, requests: 6 },
  { day: 27, requests: 0 },
  { day: 28, requests: 20 },
];

const topKinds = [
  { count: 18, icon: FileText, label: "Contenido" },
  { count: 9, icon: Image, label: "Imagen" },
  { count: 5, icon: Recycle, label: "Repurpose" },
  { count: 2, icon: Clock3, label: "Timing" },
];

const chartConfig = {
  requests: {
    color: "var(--chart-3)",
    label: "Solicitudes",
  },
} satisfies ChartConfig;

const maxRequests = Math.max(...usageDays.map((item) => item.requests), 1);

function UsageBarShape(props: BarShapeProps) {
  const { height, payload, width, x, y } = props;
  const barPayload = payload as (typeof usageDays)[number] | undefined;
  const barHeightValue = Number(height);
  const barWidthValue = Number(width);
  const xValue = Number(x);
  const yValue = Number(y);
  const requests = barPayload?.requests ?? 0;
  const fill = "var(--color-requests)";
  const fillOpacity = requests >= maxRequests * 0.8 ? 0.95 : 0.4;
  const baselineY = yValue + barHeightValue - 2;
  const barGap = 4;
  const barHeight = Math.max(0, barHeightValue - barGap);

  return (
    <g>
      <rect
        x={xValue}
        y={baselineY}
        width={barWidthValue}
        height={2}
        rx={1}
        fill={fill}
        fillOpacity={requests === 0 ? 0.25 : fillOpacity}
      />
      {requests > 0 && barHeight > 0 ? (
        <rect x={xValue} y={yValue} width={barWidthValue} height={barHeight} rx={2} fill={fill} fillOpacity={fillOpacity} />
      ) : null}
    </g>
  );
}

export function AiUsage() {
  return (
    <Card className="h-full" variant="subtle">
      <CardHeader>
        <CardTitle className="font-normal">Uso de AI</CardTitle>
        <CardDescription>Solicitudes por día en las últimas 4 semanas.</CardDescription>
      </CardHeader>

      <CardContent className="flex flex-col gap-4">
        <div className="flex items-baseline gap-1">
          <span className="text-2xl tabular-nums leading-none tracking-tight">340</span>
          <span className="text-muted-foreground text-sm">créditos usados</span>
        </div>
        <ChartContainer config={chartConfig} className="h-36 w-full">
          <BarChart data={usageDays} margin={{ bottom: 0, left: 0, right: 0, top: 0 }} barCategoryGap={3}>
            <XAxis dataKey="day" hide />
            <YAxis hide domain={[0, maxRequests + 2]} />
            <ChartTooltip cursor={false} content={<ChartTooltipContent hideLabel />} />
            <Bar dataKey="requests" fill="var(--color-requests)" shape={UsageBarShape} />
          </BarChart>
        </ChartContainer>
        <div className="grid grid-cols-2">
          {topKinds.map((kind, index) => {
            const Icon = kind.icon;
            const isLeft = index % 2 === 0;
            const isTop = index < 2;

            return (
              <div
                className={[
                  "flex items-center gap-3",
                  isLeft ? "border-border/50 border-r pr-5" : "pl-5",
                  isTop ? "border-border/50 border-b pt-1 pb-4" : "pt-4 pb-1",
                ].join(" ")}
                key={kind.label}
              >
                <Icon aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
                <span className="min-w-0 flex-1 truncate text-sm">{kind.label}</span>
                <span className="text-sm tabular-nums">{kind.count}</span>
              </div>
            );
          })}
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { Bar, BarChart, CartesianGrid, LabelList, type LabelProps, XAxis, YAxis } from "recharts";

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { type ChartConfig, ChartContainer, ChartTooltip, ChartTooltipContent } from "@/components/ui/chart";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

const chartConfig = {
  count: {
    color: "var(--chart-1)",
    label: "Publicaciones",
  },
} satisfies ChartConfig;

type BreakdownDatum = {
  count: number;
  label: string;
};

const channelsData: BreakdownDatum[] = [
  { count: 12, label: "Facebook" },
  { count: 9, label: "Instagram" },
  { count: 6, label: "WhatsApp" },
  { count: 3, label: "LinkedIn" },
];

const toolsData: BreakdownDatum[] = [
  { count: 18, label: "Contenido" },
  { count: 9, label: "Imagen" },
  { count: 5, label: "Repurpose" },
  { count: 2, label: "Timing" },
];

function renderValueLabel(props: LabelProps) {
  const { height, value, y } = props;

  return (
    <text
      className="fill-foreground"
      dominantBaseline="middle"
      dx={-6}
      fontSize={14}
      textAnchor="end"
      x="100%"
      y={Number(y) + Number(height) / 2}
    >
      {value}
    </text>
  );
}

function BreakdownBarChart({ data }: { data: BreakdownDatum[] }) {
  return (
    <ChartContainer config={chartConfig} className="h-64 w-full">
      <BarChart
        accessibilityLayer
        data={data}
        layout="vertical"
        margin={{
          left: 0,
          right: 48,
        }}
      >
        <CartesianGrid horizontal={false} vertical={false} />
        <YAxis dataKey="label" hide tickLine={false} tickMargin={10} type="category" />
        <XAxis dataKey="count" hide type="number" />
        <ChartTooltip cursor={false} content={<ChartTooltipContent indicator="line" />} />
        <Bar barSize={40} dataKey="count" fill="var(--color-count)" fillOpacity={0.5} radius={8}>
          <LabelList className="fill-foreground" dataKey="label" fontSize={14} offset={12} position="insideLeft" />
          <LabelList content={renderValueLabel} dataKey="count" />
        </Bar>
      </BarChart>
    </ChartContainer>
  );
}

export function ChannelBreakdown() {
  return (
    <Card className="h-full gap-2" variant="subtle">
      <CardHeader>
        <CardTitle className="font-normal">Distribución de publicaciones</CardTitle>
        <CardDescription>Últimas 4 semanas por canal y herramienta.</CardDescription>
      </CardHeader>

      <CardContent className="px-0">
        <Tabs defaultValue="channels" className="flex flex-col gap-3">
          <TabsList className="w-full justify-start border-b px-2.5" variant="line">
            <TabsTrigger className="flex-none font-normal" value="channels">
              Canales
            </TabsTrigger>
            <TabsTrigger className="flex-none font-normal" value="tools">
              Herramientas AI
            </TabsTrigger>
          </TabsList>

          <TabsContent value="channels" className="px-4">
            <BreakdownBarChart data={channelsData} />
          </TabsContent>

          <TabsContent value="tools" className="px-4">
            <BreakdownBarChart data={toolsData} />
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  );
}

import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";

