} as const;

export function UpcomingPosts() {
  return (
    <Card className="h-full gap-2" variant="subtle">
      <CardHeader>
        <CardTitle className="font-normal">Próximas publicaciones</CardTitle>
        <CardDescription>Lo siguiente en tu calendario de contenido.</CardDescription>
      </CardHeader>

      <CardContent className="px-0">
        <Table className="[&_td:first-child]:pl-4 [&_td:last-child]:pr-4 [&_th:first-child]:pl-4 [&_th:last-child]:pr-4">
          <TableHeader className="[&_tr]:border-border/50">
            <TableRow className="hover:bg-transparent">
              <TableHead className="h-8" />
              <TableHead className="h-8 w-28 font-normal">Canal</TableHead>
              <TableHead className="h-8 w-28 font-normal">Estado</TableHead>
              <TableHead className="h-8 w-32 text-right font-normal">Fecha</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody className="[&_tr]:border-border/50">
            {upcoming.map((post) => {
              const status = statusCopy[post.status];

              return (
                <TableRow className="hover:bg-transparent" key={post.content}>
                  <TableCell className="max-w-0 truncate py-4 font-medium">{post.content}</TableCell>
                  <TableCell className="text-muted-foreground">{post.channel}</TableCell>
                  <TableCell>
                    <Badge className="leading-none" variant={status.variant}>
                      {status.label}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-right text-muted-foreground tabular-nums">{post.date}</TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
      </CardContent>
    </Card>
  );
}

import { AiUsage } from "./_components/ai-usage";
import { ChannelBreakdown } from "./_components/channel-breakdown";
import { MetricCards } from "./_components/metric-cards";
import { PublishingActivity } from "./_components/publishing-activity";
import { UpcomingPosts } from "./_components/upcoming-posts";

export default function Page() {
  return (
    <div className="@container/main flex flex-col gap-4 md:gap-6">
      <MetricCards />
      <div className="grid grid-cols-1 items-stretch gap-4 xl:grid-cols-12">
        <div className="xl:col-span-7">
          <PublishingActivity />
        </div>
        <div className="xl:col-span-5">
          <AiUsage />
