  { count: 240, icon: FileText, label: "Contenido" },
  { count: 130, icon: Image, label: "Imagen" },
  { count: 64, icon: Recycle, label: "Repurpose" },
  { count: 31, icon: Clock3, label: "Timing" },
];

const chartConfig = {
  requests: {
    color: "var(--chart-3)",
    label: "Solicitudes",
  },
} satisfies ChartConfig;

const maxRequests = Math.max(...activityDays.map((item) => item.requests), 1);

function ActivityBarShape(props: BarShapeProps) {
  const { height, payload, width, x, y } = props;
  const barPayload = payload as (typeof activityDays)[number] | undefined;
  const barHeightValue = Number(height);
  const barWidthValue = Number(width);
  const xValue = Number(x);
  const yValue = Number(y);
  const requests = barPayload?.requests ?? 0;
  const fill = "var(--color-requests)";
  const fillOpacity = requests >= maxRequests * 0.8 ? 0.95 : 0.4;
  const baselineY = yValue + barHeightValue - 2;
  const barGap = 4;
  const barHeight = Math.max(0, barHeightValue - barGap);

  return (
    <g>
      <rect
        x={xValue}
        y={baselineY}
        width={barWidthValue}
        height={2}
        rx={1}
        fill={fill}
        fillOpacity={requests === 0 ? 0.25 : fillOpacity}
      />
      {requests > 0 && barHeight > 0 ? (
        <rect x={xValue} y={yValue} width={barWidthValue} height={barHeight} rx={2} fill={fill} fillOpacity={fillOpacity} />
      ) : null}
    </g>
  );
}

export function PlatformAiActivity() {
