          <BarChart data={activityDays} margin={{ bottom: 0, left: 0, right: 0, top: 0 }} barCategoryGap={3}>
            <XAxis dataKey="day" hide />
            <YAxis hide domain={[0, maxRequests + 4]} />
            <ChartTooltip cursor={false} content={<ChartTooltipContent hideLabel />} />
            <Bar dataKey="requests" fill="var(--color-requests)" shape={ActivityBarShape} />
          </BarChart>
        </ChartContainer>
        <div className="grid grid-cols-2">
          {topKinds.map((kind, index) => {
            const Icon = kind.icon;
            const isLeft = index % 2 === 0;
            const isTop = index < 2;

            return (
              <div
                className={[
                  "flex items-center gap-3",
                  isLeft ? "border-border/50 border-r pr-5" : "pl-5",
                  isTop ? "border-border/50 border-b pt-1 pb-4" : "pt-4 pb-1",
                ].join(" ")}
                key={kind.label}
              >
                <Icon aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
                <span className="min-w-0 flex-1 truncate text-sm">{kind.label}</span>
                <span className="text-sm tabular-nums">{kind.count}</span>
              </div>
            );
          })}
        </div>
      </CardContent>
    </Card>
  );
}

