import { Injectable } from '@nestjs/common';
import {
  aiRequests,
  fileAssets,
  publishingPosts,
  socialAccounts,
} from '@workspace/database';
import type { PortalAuthSession, PortalDashboard } from '@workspace/contracts';
import { and, count, desc, eq, gte, inArray, lt, ne, sql } from '@workspace/database/query';
import { DatabaseService } from '../database/database.service';
import {
  aiKindLabel,
  buildComparisonSeries,
  buildDayCounts,
  buildKpiChange,
  dayKeys,
  DASHBOARD_WINDOW_DAYS,
  providerLabel,
  windowStarts,
} from './dashboard.shared';

@Injectable()
export class DashboardService {
  constructor(private readonly database: DatabaseService) {}

  async getDashboard(session: PortalAuthSession): Promise<PortalDashboard> {
    const db = this.database.db;
    const workspaceId = session.workspace.id;
    const { currentStart, previousStart } = windowStarts();

    const publishedDay = sql<string>`to_char(date_trunc('day', ${publishingPosts.publishedAt}), 'YYYY-MM-DD')`;
    const requestDay = sql<string>`to_char(date_trunc('day', ${aiRequests.createdAt}), 'YYYY-MM-DD')`;

    const [
      publishedByDay,
      channelTotals,
      recentChannels,
      creditRows,
      requestsByDay,
      requestKinds,
      filesRows,
      postsByProvider,
      scheduledRows,
      draftRows,
    ] = await Promise.all([
      db
        .select({ day: publishedDay, value: count() })
        .from(publishingPosts)
        .where(
          and(
            eq(publishingPosts.workspaceId, workspaceId),
            eq(publishingPosts.status, 'published'),
            gte(publishingPosts.publishedAt, previousStart),
          ),
        )
        .groupBy(publishedDay),
      db
        .select({ value: count() })
        .from(socialAccounts)
        .where(
          and(
            eq(socialAccounts.workspaceId, workspaceId),
            eq(socialAccounts.status, 'active'),
          ),
        ),
      db
        .select({ value: count() })
        .from(socialAccounts)
        .where(
          and(
            eq(socialAccounts.workspaceId, workspaceId),
            eq(socialAccounts.status, 'active'),
            gte(socialAccounts.connectedAt, currentStart),
          ),
        ),
      db
        .select({
          period: sql<string>`case when ${aiRequests.createdAt} >= ${currentStart} then 'current' else 'previous' end`,
          value: sql<number>`coalesce(sum(${aiRequests.costUnits}), 0)::int`,
        })
        .from(aiRequests)
        .where(
          and(
            eq(aiRequests.workspaceId, workspaceId),
            eq(aiRequests.status, 'succeeded'),
            gte(aiRequests.createdAt, previousStart),
          ),
        )
        .groupBy(sql`1`),
      db
        .select({ day: requestDay, value: count() })
        .from(aiRequests)
        .where(
          and(
            eq(aiRequests.workspaceId, workspaceId),
            gte(aiRequests.createdAt, currentStart),
          ),
        )
        .groupBy(requestDay),
      db
        .select({ kind: aiRequests.kind, value: count() })
        .from(aiRequests)
        .where(
          and(
            eq(aiRequests.workspaceId, workspaceId),
            gte(aiRequests.createdAt, currentStart),
          ),
        )
        .groupBy(aiRequests.kind)
        .orderBy(desc(count())),
      db
        .select({
          period: sql<string>`case when ${fileAssets.createdAt} >= ${currentStart} then 'current' else 'previous' end`,
          value: count(),
        })
        .from(fileAssets)
        .where(
          and(
            eq(fileAssets.workspaceId, workspaceId),
            ne(fileAssets.status, 'trashed'),
            gte(fileAssets.createdAt, previousStart),
          ),
        )
        .groupBy(sql`1`),
      db
        .select({ provider: socialAccounts.providerKey, value: count() })
        .from(publishingPosts)
        .innerJoin(
          socialAccounts,
          and(
            eq(publishingPosts.socialAccountId, socialAccounts.id),
            eq(socialAccounts.workspaceId, workspaceId),
          ),
        )
        .where(
          and(
            eq(publishingPosts.workspaceId, workspaceId),
            gte(publishingPosts.createdAt, currentStart),
          ),
        )
        .groupBy(socialAccounts.providerKey)
        .orderBy(desc(count())),
      db
        .select({
          content: publishingPosts.content,
          provider: socialAccounts.providerKey,
          scheduledAt: publishingPosts.scheduledAt,
        })
        .from(publishingPosts)
        .leftJoin(
          socialAccounts,
          and(
            eq(publishingPosts.socialAccountId, socialAccounts.id),
            eq(socialAccounts.workspaceId, workspaceId),
          ),
        )
        .where(
          and(
            eq(publishingPosts.workspaceId, workspaceId),
            inArray(publishingPosts.status, ['scheduled', 'processing']),
          ),
        )
        .orderBy(publishingPosts.scheduledAt)
        .limit(5),
      db
        .select({
          content: publishingPosts.content,
          provider: socialAccounts.providerKey,
        })
        .from(publishingPosts)
        .leftJoin(
          socialAccounts,
          and(
            eq(publishingPosts.socialAccountId, socialAccounts.id),
            eq(socialAccounts.workspaceId, workspaceId),
          ),
        )
        .where(
          and(
            eq(publishingPosts.workspaceId, workspaceId),
            eq(publishingPosts.status, 'draft'),
          ),
        )
        .orderBy(desc(publishingPosts.updatedAt))
        .limit(5),
    ]);

    const publishedMap = new Map(
      publishedByDay.map((row) => [row.day, row.value]),
    );
    const publishingActivity = buildComparisonSeries(
      publishedMap,
      currentStart,
      previousStart,
    );

    const currentPublished = publishingActivity.reduce(
      (total, point) => total + point.current,
      0,
    );
    const previousPublished = publishingActivity.reduce(
      (total, point) => total + point.previous,
      0,
    );

    const creditsCurrent =
      creditRows.find((row) => row.period === 'current')?.value ?? 0;
    const creditsPrevious =
      creditRows.find((row) => row.period === 'previous')?.value ?? 0;

    const filesCurrent =
      filesRows.find((row) => row.period === 'current')?.value ?? 0;
    const filesPrevious =
      filesRows.find((row) => row.period === 'previous')?.value ?? 0;

    const activeChannels = channelTotals[0]?.value ?? 0;
    const channelsConnected = recentChannels[0]?.value ?? 0;

    const aiKinds = requestKinds.slice(0, 4).map((row) => ({
      label: aiKindLabel(row.kind),
      count: row.value,
    }));

    const upcoming = [
      ...scheduledRows.map((row) => ({
        content: row.content,
        channel: providerLabel(row.provider),
        status: 'scheduled' as const,
        date: row.scheduledAt ? row.scheduledAt.toISOString() : null,
      })),
      ...draftRows.map((row) => ({
        content: row.content,
        channel: providerLabel(row.provider),
        status: 'draft' as const,
        date: null,
      })),
    ].slice(0, 5);

    return {
      metrics: [
        {
          label: 'Publicaciones',
          value: String(currentPublished),
          change: buildKpiChange(currentPublished, previousPublished),
          description: 'frente a las 4 semanas previas',
          icon: 'calendar',
        },
        {
          label: 'Canales activos',
          value: String(activeChannels),
          change:
            channelsConnected > 0
              ? { direction: 'up' as const, label: `+${channelsConnected}` }
              : null,
          description:
            channelsConnected > 0
              ? 'conectados en las últimas 4 semanas'
              : 'sin conexiones nuevas en 4 semanas',
          icon: 'channels',
        },
        {
          label: 'Créditos AI usados',
          value: String(creditsCurrent),
          change: buildKpiChange(creditsCurrent, creditsPrevious),
          description: 'frente a las 4 semanas previas',
          icon: 'ai',
        },
        {
          label: 'Archivos nuevos',
          value: String(filesCurrent),
          change: buildKpiChange(filesCurrent, filesPrevious),
          description: 'frente a las 4 semanas previas',
          icon: 'files',
        },
      ],
      publishingActivity,
      aiUsage: {
        creditsUsed: creditsCurrent,
        days: buildDayCounts(
          new Map(requestsByDay.map((row) => [row.day, row.value])),
          dayKeys(currentStart, DASHBOARD_WINDOW_DAYS),
        ),
        kinds: aiKinds,
      },
      channels: postsByProvider.slice(0, 5).map((row) => ({
        label: providerLabel(row.provider),
        count: row.value,
      })),
      aiTools: aiKinds,
      upcoming,
    };
  }
}

export const DASHBOARD_WINDOW_DAYS = 28;

const DAY_MS = 24 * 60 * 60 * 1000;

function startOfUtcDay(date: Date): Date {
  return new Date(
    Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()),
  );
}

export function windowStarts(): { currentStart: Date; previousStart: Date } {
  const today = startOfUtcDay(new Date());
  const currentStart = new Date(
    today.getTime() - (DASHBOARD_WINDOW_DAYS - 1) * DAY_MS,
  );
  const previousStart = new Date(
    currentStart.getTime() - DASHBOARD_WINDOW_DAYS * DAY_MS,
  );
  return { currentStart, previousStart };
}

export function dayKeys(start: Date, days: number): string[] {
  return Array.from({ length: days }, (_, index) =>
    new Date(start.getTime() + index * DAY_MS).toISOString().slice(0, 10),
  );
}

export function buildDayCounts(
  counts: Map<string, number>,
  keys: string[],
): { date: string; count: number }[] {
  return keys.map((date) => ({ date, count: counts.get(date) ?? 0 }));
}

export function buildComparisonSeries(
  counts: Map<string, number>,
  currentStart: Date,
  previousStart: Date,
): { date: string; current: number; previous: number }[] {
  const currentKeys = dayKeys(currentStart, DASHBOARD_WINDOW_DAYS);
  const previousKeys = dayKeys(previousStart, DASHBOARD_WINDOW_DAYS);
  return currentKeys.map((date, index) => ({
    date,
    current: counts.get(date) ?? 0,
    previous: counts.get(previousKeys[index] ?? '') ?? 0,
  }));
}

export function buildKpiChange(
  current: number,
  previous: number,
): { direction: 'up' | 'down'; label: string } | null {
  if (previous <= 0 || current === previous) return null;
  const percent = ((current - previous) / previous) * 100;
  const rounded = Math.round(percent * 10) / 10;
  if (rounded === 0) return null;
  return {
    direction: rounded > 0 ? 'up' : 'down',
    label: `${rounded > 0 ? '+' : ''}${rounded}%`,
  };
}

const PROVIDER_LABELS: Record<string, string> = {
  facebook: 'Facebook',
  instagram: 'Instagram',
  linkedin: 'LinkedIn',
  tiktok: 'TikTok',
  whatsapp: 'WhatsApp',
  'whatsapp-status': 'WhatsApp Status',
  x: 'X',
};

export function providerLabel(providerKey: string | null): string {
  if (!providerKey) return 'Sin canal';
  const label = PROVIDER_LABELS[providerKey];
  if (label) return label;
  return providerKey.charAt(0).toUpperCase() + providerKey.slice(1);
}

const AI_KIND_LABELS: Record<string, string> = {
  ai_publishing: 'AI Publishing',
  content: 'Contenido',
  image: 'Imagen',
  planner: 'Planner',
  repurpose: 'Repurpose',
  review: 'Revisión',
  search: 'Búsqueda',
  timing: 'Timing',
  video: 'Vídeo',
};

export function aiKindLabel(kind: string): string {
  return AI_KIND_LABELS[kind] ?? kind;
}

import { Injectable } from '@nestjs/common';
import {
  aiRequests,
  billingPayments,
  billingSubscriptions,
  plans,
  users,
  workspaces,
} from '@workspace/database';
import type { AdminDashboard } from '@workspace/contracts';
import { and, count, desc, eq, gte, inArray, sql } from '@workspace/database/query';
import { DatabaseService } from '../database/database.service';
import {
  aiKindLabel,
  buildComparisonSeries,
  buildDayCounts,
  buildKpiChange,
  dayKeys,
  DASHBOARD_WINDOW_DAYS,
  windowStarts,
} from './dashboard.shared';

@Injectable()
export class AdminDashboardService {
  constructor(private readonly database: DatabaseService) {}

  async getDashboard(): Promise<AdminDashboard> {
    const db = this.database.db;
    const { currentStart, previousStart } = windowStarts();

    const userDay = sql<string>`to_char(date_trunc('day', ${users.createdAt}), 'YYYY-MM-DD')`;
    const requestDay = sql<string>`to_char(date_trunc('day', ${aiRequests.createdAt}), 'YYYY-MM-DD')`;

    const [
      userTotals,
      usersByDay,
      workspaceTotals,
      workspacesByPeriod,
      activeSubscriptions,
      subscriptionsByPlan,
      revenueRows,
      requestsByDay,
      requestKinds,
      paymentRows,
    ] = await Promise.all([
      db.select({ value: count() }).from(users),
      db
        .select({ day: userDay, value: count() })
        .from(users)
        .where(gte(users.createdAt, previousStart))
        .groupBy(userDay),
      db.select({ value: count() }).from(workspaces),
      db
        .select({
          period: sql<string>`case when ${workspaces.createdAt} >= ${currentStart} then 'current' else 'previous' end`,
          value: count(),
        })
        .from(workspaces)
        .where(gte(workspaces.createdAt, previousStart))
        .groupBy(sql`1`),
      db
        .select({ value: count() })
        .from(billingSubscriptions)
        .where(inArray(billingSubscriptions.status, ['active', 'trialing'])),
      db
        .select({ label: plans.name, value: count() })
        .from(billingSubscriptions)
        .innerJoin(plans, eq(billingSubscriptions.planId, plans.id))
        .where(inArray(billingSubscriptions.status, ['active', 'trialing']))
        .groupBy(plans.name)
        .orderBy(desc(count())),
      db
        .select({
          period: sql<string>`case when ${billingPayments.paidAt} >= ${currentStart} then 'current' else 'previous' end`,
          value: sql<number>`coalesce(sum(${billingPayments.amountMinor} - ${billingPayments.refundedAmountMinor}), 0)::int`,
          currency: billingPayments.currency,
        })
        .from(billingPayments)
        .where(
          and(
            inArray(billingPayments.status, ['paid', 'partially_refunded']),
            gte(billingPayments.paidAt, previousStart),
          ),
        )
        .groupBy(sql`1`, billingPayments.currency),
      db
        .select({ day: requestDay, value: count() })
        .from(aiRequests)
        .where(gte(aiRequests.createdAt, currentStart))
        .groupBy(requestDay),
      db
        .select({ kind: aiRequests.kind, value: count() })
        .from(aiRequests)
        .where(gte(aiRequests.createdAt, currentStart))
        .groupBy(aiRequests.kind)
        .orderBy(desc(count())),
      db
        .select({
          product: billingPayments.productLabel,
          workspace: workspaces.name,
          status: billingPayments.status,
          amountMinor: billingPayments.amountMinor,
          currency: billingPayments.currency,
          paidAt: billingPayments.paidAt,
          createdAt: billingPayments.createdAt,
        })
        .from(billingPayments)
        .innerJoin(workspaces, eq(billingPayments.workspaceId, workspaces.id))
        .orderBy(desc(billingPayments.createdAt))
        .limit(5),
    ]);

    const usersMap = new Map(usersByDay.map((row) => [row.day, row.value]));
    const userGrowth = buildComparisonSeries(
      usersMap,
      currentStart,
      previousStart,
    );
    const currentUsers = userGrowth.reduce(
      (total, point) => total + point.current,
      0,
    );
    const previousUsers = userGrowth.reduce(
      (total, point) => total + point.previous,
      0,
    );

    const workspacesCurrent =
      workspacesByPeriod.find((row) => row.period === 'current')?.value ?? 0;
    const workspacesPrevious =
      workspacesByPeriod.find((row) => row.period === 'previous')?.value ?? 0;

    const revenueCurrent = revenueRows
      .filter((row) => row.period === 'current')
      .reduce((total, row) => total + row.value, 0);
    const revenuePrevious = revenueRows
      .filter((row) => row.period === 'previous')
      .reduce((total, row) => total + row.value, 0);
    const revenueCurrency = revenueRows[0]?.currency ?? 'USD';
    const revenueFormatter = new Intl.NumberFormat('es', {
      style: 'currency',
      currency: revenueCurrency,
    });

    const totalRequests = requestsByDay.reduce(
      (total, row) => total + row.value,
      0,
    );

    return {
      metrics: [
        {
          label: 'Usuarios',
          value: String(userTotals[0]?.value ?? 0),
          change: buildKpiChange(currentUsers, previousUsers),
          description: 'registros frente a las 4 semanas previas',
          icon: 'users',
        },
        {
          label: 'Workspaces',
          value: String(workspaceTotals[0]?.value ?? 0),
          change: buildKpiChange(workspacesCurrent, workspacesPrevious),
          description: 'creación frente a las 4 semanas previas',
          icon: 'workspaces',
        },
        {
          label: 'Suscripciones activas',
          value: String(activeSubscriptions[0]?.value ?? 0),
          change: null,
          description: 'activas o en periodo de prueba',
          icon: 'subscriptions',
        },
        {
          label: 'Ingresos',
          value: revenueFormatter.format(revenueCurrent / 100),
          change: buildKpiChange(revenueCurrent, revenuePrevious),
          description: 'cobrado en las últimas 4 semanas',
          icon: 'revenue',
        },
      ],
      userGrowth,
      plans: subscriptionsByPlan.slice(0, 5).map((row) => ({
        label: row.label,
        count: row.value,
      })),
      aiActivity: {
        total: totalRequests,
        days: buildDayCounts(
          new Map(requestsByDay.map((row) => [row.day, row.value])),
          dayKeys(currentStart, DASHBOARD_WINDOW_DAYS),
        ),
        kinds: requestKinds.slice(0, 4).map((row) => ({
          label: aiKindLabel(row.kind),
          count: row.value,
        })),
      },
      recentPayments: paymentRows.map((row) => ({
        product: row.product,
        workspace: row.workspace,
        status: row.status,
        amountMinor: row.amountMinor,
        currency: row.currency,
        date: (row.paidAt ?? row.createdAt).toISOString(),
      })),
    };
  }
}

import { Controller, Get, Req } from '@nestjs/common';
import { ApiTags } from '@nestjs/swagger';
import type { FastifyRequest } from 'fastify';
import { SessionAccessService } from '../identity/session-access.service';
import { AdminDashboardService } from './admin-dashboard.service';

@ApiTags('admin-dashboard')
@Controller('v1/admin/dashboard')
export class AdminDashboardController {
  constructor(
    private readonly dashboard: AdminDashboardService,
    private readonly access: SessionAccessService,
