import type { SupportedLocale } from "@workspace/contracts"

/**
 * Español es el idioma fuente: los textos se escriben primero en `es.json` y
 * el resto de idiomas traduce esas mismas claves.
 */
export const defaultLocale = "es" satisfies SupportedLocale

export const supportedLocales = ["es", "en"] as const satisfies readonly SupportedLocale[]

/** Cookie legible por el servidor; no guarda datos de sesión, solo el idioma. */
export const localeCookieName = "zapi_locale"

export const localeCookieMaxAge = 60 * 60 * 24 * 365

export function isSupportedLocale(value: unknown): value is SupportedLocale {
  return supportedLocales.includes(value as SupportedLocale)
}

/** Un valor desconocido o ausente cae al idioma por defecto. */
export function resolveLocale(value: unknown): SupportedLocale {
  return isSupportedLocale(value) ? value : defaultLocale
}

import { cookies } from "next/headers"
import { getRequestConfig } from "next-intl/server"

import { localeCookieName, resolveLocale } from "./locales"

/**
 * El idioma se resuelve desde la cookie `zapi_locale` y cae al idioma por
 * defecto cuando falta o no está soportado. La cookie la escribe el cliente al
 * cambiar el idioma en el perfil y al sincronizar `users.locale` de la sesión,
 * de modo que el render no depende de una llamada a la API por petición.
 */
export default getRequestConfig(async () => {
  const store = await cookies()
  const locale = resolveLocale(store.get(localeCookieName)?.value)

  return {
    locale,
    messages: (await import(`../messages/${locale}.json`)).default,
  }
})

