      homeHref="/admin/dashboard"
      isItemActive={(item, pathname) =>
        isAdminNavigationItemActive(item.href, pathname)
      }
      items={items}
      navigationLabel={t("adminNavigationLabel")}
      profile={profile}
      sidebarStorageKey="zapi:admin-sidebar:v1"
    >
      {children}
    </DashboardShell>
