      toast.error("No pudimos cargar tu dashboard. Inténtalo de nuevo.")
      setHasError(true)
    } finally {
      setIsLoading(false)
    }
  }, [router])

  useEffect(() => {
    void loadDashboard()
  }, [loadDashboard])

  if (isLoading) return <DashboardLoading />

  if (hasError || !dashboard) {
    return (
