  onNextPage,
  onPreviousPage,
  page,
  pageSize,
  total,
}: PaginationProps) {
  return (
    <TablePagination
      canGoNext={page * pageSize < total}
      canGoPrevious={page > 1}
      itemLabel="registros"
      onNextPage={onNextPage}
      onPreviousPage={onPreviousPage}
      rangeEnd={Math.min(page * pageSize, total)}
      rangeStart={total ? (page - 1) * pageSize + 1 : 0}
      total={total}
    />
  )
}

