  }

  private role(value: string | null) {
    return value === 'owner'
      ? 'Propietaria'
      : value === 'admin'
        ? 'Administración'
        : value === 'member'
          ? 'Miembro'
          : 'Sin acceso';
  }

  private ledgerType(value: string) {
    return value === 'grant'
      ? 'Compra'
      : value === 'debit'
        ? 'Consumo'
        : value === 'refund'
          ? 'Reverso'
          : 'Ajuste';
  }

  private actionName(value: string) {
    return value
      .split('.')
      .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
      .join(' ');
  }

  private metadataString(value: Record<string, unknown>, key: string) {
    return typeof value[key] === 'string' ? value[key] : undefined;
  }

  private commissionStatus(value: string) {
    return value === 'pending'
      ? 'Pendiente'
      : value === 'available'
        ? 'Disponible'
        : value === 'paid'
          ? 'Pagada'
          : 'Rechazada';
  }

  private withdrawalStatus(value: string) {
    return value === 'requested'
      ? 'Pendiente'
      : value === 'approved'
        ? 'Aprobado'
        : value === 'paid'
          ? 'Pagado'
          : 'Rechazado';
  }

  private paymentStatus(value: string) {
    return value === 'paid'
      ? 'Completado'
      : value === 'pending'
        ? 'Pendiente'
        : value === 'refunded'
          ? 'Reembolsado'
          : value === 'partially_refunded'
            ? 'Reembolso parcial'
            : 'Fallido';
  }

  private subscriptionStatus(value: string) {
    return value === 'active'
      ? 'Activa'
      : value === 'trialing'
        ? 'Prueba'
        : value === 'past_due'
          ? 'En mora'
          : value === 'paused'
            ? 'Pausada'
            : value === 'canceled'
              ? 'Cancelada'
              : value === 'unpaid'
                ? 'Impaga'
                : 'Incompleta';
  }

  private slug(value: string) {
    return (
      value
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-|-$/g, '') || 'usuario'
    );
  }

  private constraint(error: unknown) {
    return (
      typeof error === 'object' &&
      error !== null &&
      'code' in error &&
      (error as { code?: string }).code === '23505'
    );
  }
}

