messages = json.load(open("apps/web/messages/es.json"))

def lookup(path):
    node = messages
    for part in path.split("."):
        if not isinstance(node, dict) or part not in node:
            return None
        node = node[part]
    return node

pattern = re.compile(r'\bt\(`([^`]*)`')
problems = []
checked = 0
for p in sorted(pathlib.Path("apps/web").rglob("*.ts*")):
    if "node_modules" in str(p) or "/messages/" in str(p):
        continue
    lines = p.read_text().split("\n")
    ns = None
    for i, line in enumerate(lines, 1):
        m = re.search(r'useTranslations(?:<[^>]*>)?\("([^"]+)"\)', line)
        if m:
            ns = m.group(1)
        for km in pattern.finditer(line):
            key = km.group(1)
            if "${" not in key:
                continue
            prefix = key.split("${")[0].rstrip(".")
            if not prefix or not ns:
                continue
            checked += 1
            full = f"{ns}.{prefix}"
            node = lookup(full)
            if node is None:
                problems.append((str(p), i, full, "no existe"))
            elif not isinstance(node, dict):
                problems.append((str(p), i, full, "no es un grupo"))

print(f"prefijos dinámicos comprobados: {checked}")
