    <Avatar size="lg">
      {account.avatarUrl ? (
        <AvatarImage
          alt={t("avatarAlt", { name: account.displayName })}
          src={account.avatarUrl}
        />
      ) : null}
      <AvatarFallback>{capabilityInitials(account)}</AvatarFallback>
    </Avatar>
  )

