export function MemberAccessDialog({
  accounts,
  actorRole,
  error,
  member,
  onOpenChange,
  onSubmit,
  pending,
}: {
  accounts: PortalTeamsResponse["accounts"]
  actorRole: PortalTeamRole
  error: string | null
  member: PortalTeamMember | null
  onOpenChange: (open: boolean) => void
  onSubmit: (input: { accountIds: string[]; role: InvitationRole }) => void
  pending: boolean
}) {
  const t = useTranslations("teams")
  const [accountIds, setAccountIds] = useState<string[]>(
    () => member?.accountIds ?? []
  )
  const [role, setRole] = useState<InvitationRole>(() =>
    member?.role === "admin" ? "admin" : "member"
  )

  useEffect(() => {
    if (error) toast.error(error)
  }, [error])

  if (!member) return null

  function toggleAccount(accountId: string, checked: boolean) {
    setAccountIds((current) =>
      checked
        ? [...new Set([...current, accountId])]
        : current.filter((id) => id !== accountId)
    )
  }

  return (
    <Sheet onOpenChange={onOpenChange} open>
      <SheetContent className="w-full gap-0 p-0 sm:max-w-md" side="right">
        <SheetHeader className="border-b">
          <SheetTitle>Acceso de {member.name}</SheetTitle>
          <SheetDescription>
            El rol y las cuentas se validan nuevamente en API y Worker en cada
            operación.
          </SheetDescription>
        </SheetHeader>
        <form
          className="flex min-h-0 flex-1 flex-col"
          noValidate
          onSubmit={(event) => {
            event.preventDefault()
            onSubmit({ accountIds, role })
          }}
        >
          <div className="flex min-h-0 flex-1 flex-col gap-5 overflow-y-auto p-4">
            <FieldGroup>
              <Field>
                <FieldLabel htmlFor="team-member-role">
                  {t("roleColumn")}
                  <span aria-hidden="true" className="text-destructive">
                    *
                  </span>
                </FieldLabel>
                {actorRole === "owner" ? (
                  <Select
                    disabled={pending}
                    onValueChange={(value) => setRole(value as InvitationRole)}
                    value={role}
                  >
                    <SelectTrigger aria-required="true" id="team-member-role">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectGroup>
                        <SelectItem value="member">
                          {t("role.member")}
                        </SelectItem>
                        <SelectItem value="admin">{t("role.admin")}</SelectItem>
                      </SelectGroup>
                    </SelectContent>
                  </Select>
                ) : (
                  <Badge variant={roleVariants[role]}>
                    {t(`role.${role}`)}
                  </Badge>
                )}
              </Field>
              <FieldSet data-disabled={role === "admin" || pending}>
                <FieldLegend variant="label">
                  {t("assignedAccounts")}
                </FieldLegend>
                {role === "admin" ? (
                  <FieldDescription>{t("adminAllAccounts")}</FieldDescription>
                ) : accounts.length ? (
                  <FieldGroup data-slot="checkbox-group" className="gap-3">
                    {accounts.map((account) => {
                      const controlId = `team-account-${account.id}`
                      return (
                        <Field key={account.id} orientation="horizontal">
                          <Checkbox
                            checked={accountIds.includes(account.id)}
                            disabled={pending}
                            id={controlId}
                            onCheckedChange={(value) =>
                              toggleAccount(account.id, value === true)
                            }
                          />
                          <FieldLabel htmlFor={controlId}>
                            <FieldContent>
                              <FieldTitle>{account.name}</FieldTitle>
                              <FieldDescription>
                                {account.detail}
                              </FieldDescription>
                            </FieldContent>
                          </FieldLabel>
                        </Field>
                      )
                    })}
                  </FieldGroup>
                ) : (
                  <FieldDescription>{t("noActiveAccounts")}</FieldDescription>
                )}
