  onOpenChange,
  onSubmit,
  open,
  pending,
}: {
  accounts: readonly GroupAccount[]
  group: PortalAccountGroup | null
  onOpenChange: (open: boolean) => void
  onSubmit: (draft: GroupDraft) => Promise<boolean>
  open: boolean
  pending: boolean
}) {
