"use client"

import { useState, type FormEvent } from "react"
import { useFormatter, useTranslations } from "next-intl"
import { Paperclip, Save, Send, Trash2 } from "lucide-react"

import type {
  BoardColumn,
  BoardLabel,
  BoardMember,
  BoardTaskDetail,
  BoardTaskPriority,
} from "@workspace/contracts"
import { Avatar, AvatarFallback } from "@workspace/ui/components/avatar"
import { Badge } from "@workspace/ui/components/badge"
import { Button } from "@workspace/ui/components/button"
import { Checkbox } from "@workspace/ui/components/checkbox"
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldGroup,
  FieldLabel,
  FieldLegend,
  FieldSet,
  FieldTitle,
} from "@workspace/ui/components/field"
import { Input } from "@workspace/ui/components/input"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@workspace/ui/components/select"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from "@workspace/ui/components/sheet"
import { Spinner } from "@workspace/ui/components/spinner"
import { Textarea } from "@workspace/ui/components/textarea"

import { initialsOf } from "./board-task-card"

const priorities: readonly BoardTaskPriority[] = ["low", "medium", "high"]

export type TaskDraft = {
  title: string
  description: string
  priority: BoardTaskPriority
  dueDate: string
  progress: number
  assigneeUserId: string
  labelIds: string[]
}

/** Valor del selector cuando no hay responsable: `""` no lo admite Select. */
const unassignedValue = "none"

export function emptyTaskDraft(): TaskDraft {
  return {
    title: "",
    description: "",
    priority: "medium",
    dueDate: "",
    progress: 0,
    assigneeUserId: unassignedValue,
    labelIds: [],
  }
}

export function draftFromTask(task: BoardTaskDetail): TaskDraft {
  return {
    title: task.title,
    description: task.description,
    priority: task.priority,
    dueDate: task.dueDate ?? "",
    progress: task.progress,
    assigneeUserId: task.assignee?.id ?? unassignedValue,
    labelIds: [...task.labelIds],
  }
}

export function taskDraftToInput(draft: TaskDraft) {
  return {
    title: draft.title.trim(),
    description: draft.description.trim(),
    priority: draft.priority,
    dueDate: draft.dueDate || null,
    progress: draft.progress,
    assigneeUserId:
      draft.assigneeUserId === unassignedValue ? null : draft.assigneeUserId,
    labelIds: draft.labelIds,
  }
}

export function TaskSheet({
  canDelete,
  column,
  labels,
  members,
  onAddComment,
  onDelete,
  onOpenChange,
  onRemoveAttachment,
  onSubmit,
  open,
  pending,
  task,
}: {
  canDelete: boolean
  column: BoardColumn | null
  labels: readonly BoardLabel[]
  members: readonly BoardMember[]
  onAddComment: (body: string) => Promise<boolean>
  onDelete: () => void
  onOpenChange: (open: boolean) => void
  onRemoveAttachment: (attachmentId: string) => void
  onSubmit: (draft: TaskDraft) => Promise<boolean>
  open: boolean
  pending: boolean
  task: BoardTaskDetail | null
}) {
  const t = useTranslations("boards")
  const format = useFormatter()
  const [draft, setDraft] = useState<TaskDraft>(emptyTaskDraft)
  const [comment, setComment] = useState("")
  const [lastTaskId, setLastTaskId] = useState<string | null>(null)
  const [wasOpen, setWasOpen] = useState(open)

  // Ajustar el estado durante el render en vez de en un efecto: la hoja parte
  // de la tarea elegida sin encadenar un segundo render.
  const taskId = task?.id ?? null
  if (open !== wasOpen || taskId !== lastTaskId) {
    setWasOpen(open)
    setLastTaskId(taskId)
    if (open) {
      setDraft(task ? draftFromTask(task) : emptyTaskDraft())
      setComment("")
    }
  }

  function toggleLabel(labelId: string, checked: boolean) {
    setDraft((current) => ({
      ...current,
      labelIds: checked
        ? [...new Set([...current.labelIds, labelId])]
        : current.labelIds.filter((id) => id !== labelId),
    }))
  }

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const saved = await onSubmit(draft)
    if (saved) onOpenChange(false)
  }

  async function sendComment() {
    const body = comment.trim()
    if (!body) return
    if (await onAddComment(body)) setComment("")
  }

  return (
    <Sheet onOpenChange={onOpenChange} open={open}>
      <SheetContent className="w-full gap-0 p-0 sm:max-w-xl" side="right">
        <SheetHeader className="border-b">
          <SheetTitle>{task ? t("editTask") : t("createTask")}</SheetTitle>
          <SheetDescription>
            {column
              ? t("taskInColumn", { name: column.name })
              : t("taskSheetDescription")}
          </SheetDescription>
        </SheetHeader>
        <form
          aria-busy={pending}
          className="flex min-h-0 flex-1 flex-col"
          noValidate
          onSubmit={(event) => void submit(event)}
        >
          <div className="flex min-h-0 flex-1 flex-col gap-5 overflow-y-auto p-4">
            <FieldGroup>
              <Field>
                <FieldLabel htmlFor="board-task-title">
                  {t("titleLabel")}
                  <span aria-hidden="true" className="text-destructive">
                    *
                  </span>
                </FieldLabel>
                <Input
                  aria-required="true"
                  disabled={pending}
                  id="board-task-title"
                  maxLength={200}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      title: event.target.value,
                    }))
                  }
                  placeholder={t("titlePlaceholder")}
                  value={draft.title}
                />
              </Field>
              <Field>
                <FieldLabel htmlFor="board-task-description">
                  {t("descriptionLabel")}
                </FieldLabel>
                <Textarea
                  disabled={pending}
                  id="board-task-description"
                  maxLength={5000}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      description: event.target.value,
                    }))
                  }
                  placeholder={t("descriptionPlaceholder")}
                  rows={4}
                  value={draft.description}
                />
              </Field>
              <div className="grid gap-4 sm:grid-cols-2">
                <Field>
                  <FieldLabel htmlFor="board-task-priority">
                    {t("priorityLabel")}
                  </FieldLabel>
                  <Select
                    disabled={pending}
                    onValueChange={(value) =>
                      setDraft((current) => ({
                        ...current,
                        priority: value as BoardTaskPriority,
                      }))
                    }
                    value={draft.priority}
                  >
                    <SelectTrigger id="board-task-priority">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectGroup>
                        {priorities.map((priority) => (
                          <SelectItem key={priority} value={priority}>
                            {t(`priority.${priority}`)}
                          </SelectItem>
                        ))}
                      </SelectGroup>
                    </SelectContent>
                  </Select>
                </Field>
                <Field>
                  <FieldLabel htmlFor="board-task-assignee">
                    {t("assigneeLabel")}
                  </FieldLabel>
                  <Select
                    disabled={pending}
                    onValueChange={(value) =>
                      setDraft((current) => ({
                        ...current,
                        assigneeUserId: value,
                      }))
                    }
                    value={draft.assigneeUserId}
                  >
                    <SelectTrigger id="board-task-assignee">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectGroup>
                        <SelectItem value={unassignedValue}>
                          {t("unassigned")}
                        </SelectItem>
                        {members.map((member) => (
                          <SelectItem key={member.id} value={member.id}>
                            {member.name}
                          </SelectItem>
                        ))}
                      </SelectGroup>
                    </SelectContent>
                  </Select>
                </Field>
                <Field>
                  <FieldLabel htmlFor="board-task-due">
                    {t("dueDateLabel")}
                  </FieldLabel>
                  <Input
                    disabled={pending}
                    id="board-task-due"
                    onChange={(event) =>
                      setDraft((current) => ({
                        ...current,
                        dueDate: event.target.value,
                      }))
                    }
                    type="date"
                    value={draft.dueDate}
                  />
                </Field>
                <Field>
                  <FieldLabel htmlFor="board-task-progress">
                    {t("progressLabel")}
                  </FieldLabel>
                  <Input
                    disabled={pending}
                    id="board-task-progress"
                    max={100}
                    min={0}
                    onChange={(event) =>
                      setDraft((current) => ({
                        ...current,
                        progress: Math.max(
                          0,
                          Math.min(100, Number(event.target.value) || 0)
                        ),
                      }))
                    }
                    type="number"
                    value={String(draft.progress)}
                  />
                </Field>
              </div>
              {labels.length ? (
                <FieldSet data-disabled={pending}>
                  <FieldLegend variant="label">{t("labelsLegend")}</FieldLegend>
                  <FieldGroup className="gap-3" data-slot="checkbox-group">
                    {labels.map((label) => {
                      const controlId = `board-label-${label.id}`
                      return (
                        <Field key={label.id} orientation="horizontal">
                          <Checkbox
                            checked={draft.labelIds.includes(label.id)}
                            disabled={pending}
                            id={controlId}
                            onCheckedChange={(value) =>
                              toggleLabel(label.id, value === true)
                            }
                          />
                          <FieldLabel htmlFor={controlId}>
                            <FieldContent>
                              <FieldTitle>{label.name}</FieldTitle>
                            </FieldContent>
                          </FieldLabel>
                        </Field>
                      )
                    })}
                  </FieldGroup>
                </FieldSet>
              ) : null}
            </FieldGroup>

            {task ? (
              <FieldSet>
                <FieldLegend variant="label">
                  {t("attachmentsLegend")}
                </FieldLegend>
                {task.attachments.length ? (
                  <ul className="grid gap-2">
                    {task.attachments.map((attachment) => (
                      <li
                        className="flex items-center justify-between gap-3 rounded-lg border px-3 py-2"
                        key={attachment.id}
                      >
                        <span className="flex min-w-0 items-center gap-2">
                          <Paperclip
                            aria-hidden="true"
                            className="size-4 shrink-0 text-muted-foreground"
                          />
                          <span className="truncate text-sm">
                            {attachment.name}
                          </span>
                        </span>
                        <Button
                          aria-label={t("removeAttachment", {
                            name: attachment.name,
                          })}
                          disabled={pending}
                          onClick={() => onRemoveAttachment(attachment.id)}
                          size="icon-sm"
                          type="button"
                          variant="ghost"
                        >
                          <Trash2 />
                        </Button>
                      </li>
                    ))}
                  </ul>
                ) : (
                  <FieldDescription>{t("noAttachments")}</FieldDescription>
                )}
              </FieldSet>
            ) : null}

            {task ? (
              <FieldSet>
                <FieldLegend variant="label">{t("commentsLegend")}</FieldLegend>
                {task.comments.length ? (
                  <ul className="grid gap-3">
                    {task.comments.map((entry) => (
                      <li className="grid gap-1" key={entry.id}>
                        <span className="flex items-center gap-2">
                          <Avatar className="size-5 after:rounded-sm">
                            <AvatarFallback className="rounded-sm text-[10px]">
                              {initialsOf(entry.author?.name ?? "?")}
                            </AvatarFallback>
                          </Avatar>
                          <span className="text-sm font-medium">
                            {entry.author?.name ?? t("unknownAuthor")}
                          </span>
                          <Badge variant="neutral">
                            {format.dateTime(new Date(entry.createdAt), "date")}
                          </Badge>
                        </span>
                        <p className="text-sm whitespace-pre-line text-muted-foreground">
                          {entry.body}
                        </p>
                      </li>
                    ))}
                  </ul>
                ) : (
                  <FieldDescription>{t("noComments")}</FieldDescription>
                )}
                <Field>
                  <FieldLabel htmlFor="board-task-comment">
                    {t("addComment")}
                  </FieldLabel>
                  <Textarea
                    disabled={pending}
                    id="board-task-comment"
                    maxLength={5000}
                    onChange={(event) => setComment(event.target.value)}
                    placeholder={t("commentPlaceholder")}
                    rows={3}
                    value={comment}
                  />
                  <Button
                    className="justify-self-end"
                    disabled={pending || !comment.trim()}
                    onClick={() => void sendComment()}
                    type="button"
                    variant="brand-secondary"
                  >
                    <Send data-icon="inline-start" />
                    {t("sendComment")}
                  </Button>
                </Field>
              </FieldSet>
            ) : null}
          </div>
          <SheetFooter className="flex-row justify-between border-t">
            {task && canDelete ? (
              <Button
                disabled={pending}
                onClick={onDelete}
                type="button"
                variant="destructive"
              >
                <Trash2 data-icon="inline-start" />
                {t("deleteTask")}
              </Button>
            ) : (
              <span />
            )}
            <span className="flex gap-2">
              <Button
                disabled={pending}
                onClick={() => onOpenChange(false)}
                type="button"
                variant="brand-secondary"
              >
                {t("cancel")}
              </Button>
              <Button disabled={pending || !draft.title.trim()} type="submit">
                {pending ? (
                  <Spinner data-icon="inline-start" size={16} />
                ) : (
                  <Save aria-hidden="true" data-icon="inline-start" />
                )}
                {t("save")}
              </Button>
            </span>
          </SheetFooter>
        </form>
      </SheetContent>
    </Sheet>
  )
}

"use client"

import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { move } from "@dnd-kit/helpers"
import {
  DragDropProvider,
  DragOverlay,
  type DragEndEvent,
  type DragOverEvent,
  type DragStartEvent,
} from "@dnd-kit/react"
import { CircleAlert, Plus, Search, SlidersHorizontal } from "lucide-react"

import { ApiError, boardsApi } from "@workspace/api-client"
import type {
  BoardColumn,
  BoardResponse,
  BoardTask,
  BoardTaskDetail,
} from "@workspace/contracts"
import { Button } from "@workspace/ui/components/button"
import { EmptyState } from "@workspace/ui/components/empty-state"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@workspace/ui/components/input-group"
import { PageLoading } from "@/components/page-loading"
import { RetryButton } from "@workspace/ui/components/retry-button"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@workspace/ui/components/select"
import { toast } from "@workspace/ui/components/toast"

import { useApiErrorMessage } from "@/lib/api-error-message"
import { loginPath } from "@/features/identity/login-redirect"

import { BoardColumnSection } from "./board-column"
import { BoardTaskCard } from "./board-task-card"
import { ColumnSheet } from "./column-sheet"
import {
  TaskSheet,
  emptyTaskDraft,
  taskDraftToInput,
  type TaskDraft,
} from "./task-sheet"

type BoardState = Record<string, BoardTask[]>

const allAssignees = "all"
const allPriorities = "all"

function groupByColumn(
  columns: readonly BoardColumn[],
  tasks: readonly BoardTask[]
): BoardState {
  const state: BoardState = {}
  for (const column of columns) state[column.id] = []
  for (const task of tasks) {
    // Una tarea cuya columna se borró mientras se miraba el tablero no puede
    // tumbar el render: se descarta hasta la siguiente carga.
    state[task.columnId]?.push(task)
  }
  return state
}

function errorCode(error: unknown) {
  return error instanceof ApiError ? error.code : undefined
}

export function BoardPage() {
  const t = useTranslations("boards")
  const router = useRouter()
  const apiErrorMessage = useApiErrorMessage()

  const [data, setData] = useState<BoardResponse | null>(null)
  const [board, setBoard] = useState<BoardState>({})
  const [columnOrder, setColumnOrder] = useState<string[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [loadFailed, setLoadFailed] = useState(false)
  const [pending, setPending] = useState(false)
  const [query, setQuery] = useState("")
  const [assignee, setAssignee] = useState(allAssignees)
  const [priority, setPriority] = useState(allPriorities)

  const [taskSheetOpen, setTaskSheetOpen] = useState(false)
  const [activeTask, setActiveTask] = useState<BoardTaskDetail | null>(null)
  const [targetColumnId, setTargetColumnId] = useState<string | null>(null)
  const [columnSheetOpen, setColumnSheetOpen] = useState(false)
  const [editingColumn, setEditingColumn] = useState<BoardColumn | null>(null)

  const boardBeforeDrag = useRef<BoardState>({})

  const starterNames = useMemo(
    () => ({
      todo: t("starter.todo"),
      doing: t("starter.doing"),
      done: t("starter.done"),
    }),
    [t]
  )

  const load = useCallback(async () => {
    setIsLoading(true)
    setLoadFailed(false)
    try {
      const response = await boardsApi.board(
        {
          q: query.trim() || undefined,
          assigneeId: assignee === allAssignees ? undefined : assignee,
          priority:
            priority === allPriorities
              ? undefined
              : (priority as BoardTask["priority"]),
        },
        starterNames
      )
      setData(response)
      setBoard(groupByColumn(response.columns, response.tasks))
      setColumnOrder(response.columns.map((column) => column.id))
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        router.replace(loginPath())
        return
      }
      setLoadFailed(true)
      toast.error(apiErrorMessage(errorCode(error)))
    } finally {
      setIsLoading(false)
    }
  }, [apiErrorMessage, assignee, priority, query, router, starterNames])

  useEffect(() => {
    // El temporizador saca el primer `setState` del cuerpo del efecto y cancela
    // la carga anterior mientras se escribe en el buscador.
    const timer = setTimeout(() => void load(), query ? 300 : 0)
    return () => clearTimeout(timer)
  }, [load, query])

  const columns = useMemo(
    () =>
      columnOrder.flatMap(
        (id) => data?.columns.find((column) => column.id === id) ?? []
      ),
    [columnOrder, data?.columns]
  )
  const abilities = data?.abilities
  const canManageTasks = Boolean(abilities?.manageTasks)
  const canManageColumns = Boolean(abilities?.manageColumns)

  function handleDragStart(event: DragStartEvent) {
    if (event.operation.source?.type === "task") boardBeforeDrag.current = board
  }

  function handleDragOver(event: DragOverEvent) {
    if (event.operation.source?.type === "task") {
      setBoard((current) => move(current, event))
    }
  }

  async function handleDragEnd(event: DragEndEvent) {
    const { source } = event.operation
    if (!source) return

    if (event.canceled) {
      if (source.type === "task") setBoard(boardBeforeDrag.current)
      return
    }

    if (source.type === "column") {
      const previous = columnOrder
      const next = move(columnOrder, event)
      setColumnOrder(next)
      try {
        await boardsApi.reorderColumns({ columnIds: next })
      } catch (error) {
        setColumnOrder(previous)
        toast.error(apiErrorMessage(errorCode(error)))
      }
      return
    }

    // El destino se lee del estado que ya pintó `onDragOver`: la API recibe
    // columna e índice finales, no un desplazamiento.
    const taskId = String(source.id)
    const columnId = Object.keys(board).find((id) =>
      board[id]?.some((task) => task.id === taskId)
    )
    if (!columnId) return
    const position = board[columnId]!.findIndex((task) => task.id === taskId)

    try {
      await boardsApi.moveTask(taskId, { columnId, position })
    } catch (error) {
      setBoard(boardBeforeDrag.current)
      toast.error(apiErrorMessage(errorCode(error)))
    }
  }

  function openNewTask(columnId: string) {
    setActiveTask(null)
    setTargetColumnId(columnId)
    setTaskSheetOpen(true)
  }

  async function openTask(task: BoardTask) {
    setTargetColumnId(task.columnId)
    setTaskSheetOpen(true)
    try {
      setActiveTask(await boardsApi.task(task.id))
    } catch (error) {
      setTaskSheetOpen(false)
      toast.error(apiErrorMessage(errorCode(error)))
    }
  }

  async function saveTask(draft: TaskDraft) {
    setPending(true)
    try {
      const input = taskDraftToInput(draft)
      if (activeTask) {
        await boardsApi.updateTask(activeTask.id, input)
      } else if (targetColumnId) {
        await boardsApi.createTask({ ...input, columnId: targetColumnId })
      }
      await load()
      toast.success(t("taskSaved"))
      return true
    } catch (error) {
      toast.error(apiErrorMessage(errorCode(error)))
      return false
    } finally {
      setPending(false)
    }
  }

  async function addComment(body: string) {
    if (!activeTask) return false
    setPending(true)
    try {
      setActiveTask(await boardsApi.addComment(activeTask.id, { body }))
      await load()
      return true
    } catch (error) {
      toast.error(apiErrorMessage(errorCode(error)))
      return false
    } finally {
      setPending(false)
    }
  }

  async function removeAttachment(attachmentId: string) {
    if (!activeTask) return
    setPending(true)
    try {
      setActiveTask(
        await boardsApi.removeAttachment(activeTask.id, attachmentId)
      )
      await load()
    } catch (error) {
      toast.error(apiErrorMessage(errorCode(error)))
    } finally {
      setPending(false)
    }
  }

  async function deleteTask() {
    if (!activeTask) return
    setPending(true)
    try {
      await boardsApi.deleteTask(activeTask.id)
      setTaskSheetOpen(false)
      await load()
      toast.success(t("taskDeleted"))
    } catch (error) {
      toast.error(apiErrorMessage(errorCode(error)))
    } finally {
      setPending(false)
    }
  }

  async function deleteColumn(column: BoardColumn) {
    setPending(true)
    try {
      await boardsApi.deleteColumn(column.id)
      await load()
      toast.success(t("columnDeleted"))
    } catch (error) {
      toast.error(apiErrorMessage(errorCode(error)))
    } finally {
      setPending(false)
    }
  }

  if (isLoading && !data) return <PageLoading />

  if (loadFailed && !data) {
    return (
      <EmptyState
        action={<RetryButton onClick={() => void load()} />}
        description={t("loadFailedDescription")}
        icon={CircleAlert}
        title={t("loadFailed")}
      />
    )
  }

  return (
    <div
      className="flex h-[calc(100dvh-var(--dashboard-header-height))] min-h-0 min-w-0 flex-col overflow-hidden"
      data-content-padding="false"
    >
      <div className="flex shrink-0 flex-col gap-3 border-b px-4 py-3 lg:flex-row lg:items-center lg:justify-between lg:px-6">
        <div className="min-w-0">
          <h1 className="truncate text-lg font-semibold">{t("pageTitle")}</h1>
          <p className="truncate text-sm text-muted-foreground">
            {t("pageDescription")}
          </p>
        </div>

        <div className="flex min-w-0 flex-col gap-2 sm:flex-row sm:flex-wrap sm:items-center 2xl:justify-end">
          <InputGroup className="min-w-0 sm:w-64">
            <InputGroupInput
              aria-label={t("searchLabel")}
              onChange={(event) => setQuery(event.target.value)}
              placeholder={t("searchPlaceholder")}
              type="search"
              value={query}
            />
            <InputGroupAddon>
              <Search />
            </InputGroupAddon>
          </InputGroup>
          <Select onValueChange={setAssignee} value={assignee}>
            <SelectTrigger
              aria-label={t("assigneeFilter")}
              className="w-full sm:w-44"
            >
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectGroup>
                <SelectItem value={allAssignees}>
                  {t("allAssignees")}
                </SelectItem>
                <SelectItem value="me">{t("assignedToMe")}</SelectItem>
                {data?.members.map((member) => (
                  <SelectItem key={member.id} value={member.id}>
                    {member.name}
                  </SelectItem>
                ))}
              </SelectGroup>
            </SelectContent>
          </Select>
          <Select onValueChange={setPriority} value={priority}>
            <SelectTrigger
              aria-label={t("priorityFilter")}
              className="w-full sm:w-40"
            >
              <SlidersHorizontal data-icon="inline-start" />
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectGroup>
                <SelectItem value={allPriorities}>
                  {t("allPriorities")}
                </SelectItem>
                <SelectItem value="high">{t("priority.high")}</SelectItem>
                <SelectItem value="medium">{t("priority.medium")}</SelectItem>
                <SelectItem value="low">{t("priority.low")}</SelectItem>
              </SelectGroup>
            </SelectContent>
          </Select>
          {canManageColumns ? (
            <Button
              className="w-full sm:w-auto"
              onClick={() => {
                setEditingColumn(null)
                setColumnSheetOpen(true)
              }}
              variant="brand-secondary"
            >
              <Plus data-icon="inline-start" />
              {t("addColumn")}
            </Button>
          ) : null}
          {canManageTasks && columns.length ? (
            <Button
              className="w-full sm:w-auto"
              onClick={() => openNewTask(columns[0]!.id)}
            >
              <Plus data-icon="inline-start" />
              {t("addTask")}
            </Button>
          ) : null}
        </div>
      </div>

      {columns.length ? (
        <DragDropProvider
          onDragEnd={(event) => void handleDragEnd(event)}
          onDragOver={handleDragOver}
          onDragStart={handleDragStart}
        >
          <div className="scrollbar-thin min-h-0 min-w-0 flex-1 overflow-x-auto overflow-y-hidden bg-muted/25 px-4 pt-4 pb-0 [scrollbar-color:var(--border)_transparent] lg:px-5 lg:pt-5 [&::-webkit-scrollbar]:h-1 [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-border [&::-webkit-scrollbar-track]:bg-transparent">
            <div
              className="inline-grid h-full min-w-full gap-4"
              style={{
                gridTemplateColumns: `repeat(${columns.length}, minmax(20rem, 1fr))`,
              }}
            >
              {columns.map((column, index) => (
                <BoardColumnSection
                  canManageColumns={canManageColumns}
                  canManageTasks={canManageTasks}
                  column={column}
                  index={index}
                  key={column.id}
                  labels={data?.labels ?? []}
                  onAddTask={() => openNewTask(column.id)}
                  onDeleteColumn={() => void deleteColumn(column)}
                  onEditColumn={() => {
                    setEditingColumn(column)
                    setColumnSheetOpen(true)
                  }}
                  onOpenTask={(task) => void openTask(task)}
                  tasks={board[column.id] ?? []}
                />
              ))}
            </div>
          </div>
          <DragOverlay dropAnimation={null}>
            {(source) => {
              const dragged = source.data as
                | { type: "task"; task: BoardTask }
                | undefined
              if (source.type !== "task" || !dragged) return null
              return (
                <BoardTaskCard
                  isOverlay
                  labels={data?.labels ?? []}
                  task={dragged.task}
                />
              )
            }}
          </DragOverlay>
        </DragDropProvider>
      ) : (
        <div className="flex min-h-0 flex-1 items-center justify-center bg-muted/25 p-6">
          <EmptyState
            description={t("emptyBoardDescription")}
            title={t("emptyBoard")}
          />
        </div>
      )}

      <TaskSheet
        canDelete={Boolean(abilities?.deleteTasks)}
        column={
          columns.find((column) => column.id === targetColumnId) ?? null
        }
        labels={data?.labels ?? []}
        members={data?.members ?? []}
        onAddComment={addComment}
        onDelete={() => void deleteTask()}
        onOpenChange={setTaskSheetOpen}
        onRemoveAttachment={(id) => void removeAttachment(id)}
        onSubmit={saveTask}
        open={taskSheetOpen}
        pending={pending}
        task={activeTask}
      />

      <ColumnSheet
        column={editingColumn}
        onOpenChange={setColumnSheetOpen}
        onSaved={() => void load()}
        open={columnSheetOpen}
      />
    </div>
  )
}

"use client"

import { useState, type FormEvent } from "react"
import { useTranslations } from "next-intl"
import { Save } from "lucide-react"

import { ApiError, boardsApi } from "@workspace/api-client"
import type { BoardColumn } from "@workspace/contracts"
import { Button } from "@workspace/ui/components/button"
import { Checkbox } from "@workspace/ui/components/checkbox"
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldGroup,
  FieldLabel,
  FieldTitle,
} from "@workspace/ui/components/field"
import { Input } from "@workspace/ui/components/input"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@workspace/ui/components/select"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from "@workspace/ui/components/sheet"
import { Spinner } from "@workspace/ui/components/spinner"
import { toast } from "@workspace/ui/components/toast"

import { useApiErrorMessage } from "@/lib/api-error-message"

/** Misma paleta que Groups, para que el color signifique lo mismo en todo V2. */
const columnColors = [
  { labelKey: "color.blue", value: "#2563eb" },
  { labelKey: "color.green", value: "#16a34a" },
  { labelKey: "color.amber", value: "#d97706" },
  { labelKey: "color.red", value: "#dc2626" },
  { labelKey: "color.violet", value: "#7c3aed" },
  { labelKey: "color.gray", value: "#475569" },
] as const

type ColumnDraft = {
  name: string
  color: string
  isTerminal: boolean
  wipLimit: string
}

const emptyDraft: ColumnDraft = {
  name: "",
  color: columnColors[0].value,
  isTerminal: false,
  wipLimit: "",
}

function draftFrom(column: BoardColumn): ColumnDraft {
  return {
    name: column.name,
    color: column.color,
    isTerminal: column.isTerminal,
    wipLimit: column.wipLimit === null ? "" : String(column.wipLimit),
  }
}

export function ColumnSheet({
  column,
  onOpenChange,
  onSaved,
  open,
}: {
  column: BoardColumn | null
  onOpenChange: (open: boolean) => void
  onSaved: () => void
  open: boolean
}) {
  const t = useTranslations("boards")
  const apiErrorMessage = useApiErrorMessage()
  const [draft, setDraft] = useState<ColumnDraft>(emptyDraft)
  const [pending, setPending] = useState(false)
  const [lastColumnId, setLastColumnId] = useState<string | null>(null)
  const [wasOpen, setWasOpen] = useState(open)

  // Ajustar el estado durante el render en vez de en un efecto.
  const columnId = column?.id ?? null
  if (open !== wasOpen || columnId !== lastColumnId) {
    setWasOpen(open)
    setLastColumnId(columnId)
    if (open) setDraft(column ? draftFrom(column) : emptyDraft)
  }

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const name = draft.name.trim()
    if (!name) return
    const wipLimit = draft.wipLimit ? Number(draft.wipLimit) : null
    setPending(true)
    try {
      const input = {
        name,
        color: draft.color,
        isTerminal: draft.isTerminal,
        wipLimit,
      }
      if (column) {
        await boardsApi.updateColumn(column.id, input)
      } else {
        await boardsApi.createColumn(input)
      }
      onSaved()
      onOpenChange(false)
      toast.success(t("columnSaved"))
    } catch (error) {
      toast.error(
        apiErrorMessage(error instanceof ApiError ? error.code : undefined)
      )
    } finally {
      setPending(false)
    }
  }

  return (
    <Sheet onOpenChange={onOpenChange} open={open}>
      <SheetContent className="w-full gap-0 p-0 sm:max-w-md" side="right">
        <SheetHeader className="border-b">
          <SheetTitle>
            {column ? t("editColumnTitle") : t("createColumnTitle")}
          </SheetTitle>
          <SheetDescription>{t("columnSheetDescription")}</SheetDescription>
        </SheetHeader>
        <form
          aria-busy={pending}
          className="flex min-h-0 flex-1 flex-col"
          noValidate
          onSubmit={(event) => void submit(event)}
        >
          <div className="flex min-h-0 flex-1 flex-col gap-5 overflow-y-auto p-4">
            <FieldGroup>
              <Field>
                <FieldLabel htmlFor="board-column-name">
                  {t("columnNameLabel")}
                  <span aria-hidden="true" className="text-destructive">
                    *
                  </span>
                </FieldLabel>
                <Input
                  aria-required="true"
                  disabled={pending}
                  id="board-column-name"
                  maxLength={60}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      name: event.target.value,
                    }))
                  }
                  value={draft.name}
                />
              </Field>
              <Field>
                <FieldLabel htmlFor="board-column-color">
                  {t("columnColorLabel")}
                </FieldLabel>
                <Select
                  disabled={pending}
                  onValueChange={(value) =>
                    setDraft((current) => ({ ...current, color: value }))
                  }
                  value={draft.color}
                >
                  <SelectTrigger id="board-column-color">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectGroup>
                      {columnColors.map((color) => (
                        <SelectItem key={color.value} value={color.value}>
                          {t(color.labelKey)}
                        </SelectItem>
                      ))}
                    </SelectGroup>
                  </SelectContent>
                </Select>
              </Field>
              <Field>
                <FieldLabel htmlFor="board-column-wip">
                  {t("wipLimitLabel")}
                </FieldLabel>
                <Input
                  disabled={pending}
                  id="board-column-wip"
                  max={999}
                  min={1}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      wipLimit: event.target.value,
                    }))
                  }
                  placeholder={t("wipLimitPlaceholder")}
                  type="number"
                  value={draft.wipLimit}
                />
                <FieldDescription>{t("wipLimitHint")}</FieldDescription>
              </Field>
              <Field orientation="horizontal">
                <Checkbox
                  checked={draft.isTerminal}
                  disabled={pending}
                  id="board-column-terminal"
                  onCheckedChange={(value) =>
                    setDraft((current) => ({
                      ...current,
                      isTerminal: value === true,
                    }))
                  }
                />
                <FieldLabel htmlFor="board-column-terminal">
                  <FieldContent>
                    <FieldTitle>{t("terminalLabel")}</FieldTitle>
                    <FieldDescription>{t("terminalHint")}</FieldDescription>
                  </FieldContent>
                </FieldLabel>
              </Field>
            </FieldGroup>
          </div>
          <SheetFooter className="flex-row justify-end border-t">
            <Button
              disabled={pending}
              onClick={() => onOpenChange(false)}
              type="button"
              variant="brand-secondary"
            >
              {t("cancel")}
            </Button>
            <Button disabled={pending || !draft.name.trim()} type="submit">
              {pending ? (
                <Spinner data-icon="inline-start" size={16} />
              ) : (
                <Save aria-hidden="true" data-icon="inline-start" />
              )}
              {t("save")}
            </Button>
          </SheetFooter>
        </form>
      </SheetContent>
    </Sheet>
  )
}

"use client"

import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { useFormatter, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { move } from "@dnd-kit/helpers"
import { DragDropProvider, type DragEndEvent } from "@dnd-kit/react"
import { useSortable } from "@dnd-kit/react/sortable"
import { CollisionPriority } from "@dnd-kit/abstract"
import { useDroppable } from "@dnd-kit/react"
import { CalendarClock, CircleAlert, Images, Lock } from "lucide-react"

import { ApiError, boardsApi } from "@workspace/api-client"
import type {
  ContentBoardCard,
  ContentBoardColumn,
} from "@workspace/contracts"
import { Badge } from "@workspace/ui/components/badge"
import { EmptyState } from "@workspace/ui/components/empty-state"
import { PageLoading } from "@/components/page-loading"
import { RetryButton } from "@workspace/ui/components/retry-button"
import { toast } from "@workspace/ui/components/toast"
import { cn } from "@workspace/ui/lib/utils"

import { useApiErrorMessage } from "@/lib/api-error-message"
import { loginPath } from "@/features/identity/login-redirect"

type ContentBoardState = Record<ContentBoardColumn, ContentBoardCard[]>

/**
 * Las columnas son los estados del dominio, no columnas configurables: quien
 * decide `processing`, `published` y `failed` es el worker.
 */
const columnOrder: readonly ContentBoardColumn[] = [
  "draft",
  "scheduled",
  "processing",
  "published",
  "failed",
]

/** Solo estos dos estados se pueden cambiar arrastrando. */
const draggableColumns = new Set<ContentBoardColumn>(["draft", "scheduled"])

const statusVariants: Record<
  ContentBoardColumn,
  "neutral" | "info" | "warning" | "success" | "destructive"
> = {
  draft: "neutral",
  scheduled: "info",
  processing: "warning",
  published: "success",
  failed: "destructive",
}

function emptyState(): ContentBoardState {
  return {
    draft: [],
    scheduled: [],
    processing: [],
    published: [],
    failed: [],
  }
}

function groupByStatus(cards: readonly ContentBoardCard[]) {
  const state = emptyState()
  for (const card of cards) state[card.status].push(card)
  return state
}

function errorCode(error: unknown) {
  return error instanceof ApiError ? error.code : undefined
}

function ContentCard({ card }: { card: ContentBoardCard }) {
  const t = useTranslations("contentBoard")
  const format = useFormatter()

  return (
    <article className="flex flex-col gap-3 rounded-xl border bg-card p-4 text-card-foreground shadow-xs">
      <div className="flex items-start justify-between gap-3">
        <p className="line-clamp-3 min-w-0 text-sm leading-5">
          {card.content || t("noContent")}
        </p>
        <Badge className="shrink-0" variant={statusVariants[card.status]}>
          {t(`status.${card.status}`)}
        </Badge>
      </div>
      <div className="flex flex-wrap items-center gap-3 text-sm text-muted-foreground">
        <span className="truncate">{card.accountName ?? t("noAccount")}</span>
        {card.mediaCount ? (
          <span className="flex items-center gap-1.5">
            <Images className="size-3.5" />
            {card.mediaCount}
          </span>
        ) : null}
        {card.scheduledAt ? (
          <span className="flex items-center gap-1.5">
            <CalendarClock className="size-3.5" />
            {format.dateTime(new Date(card.scheduledAt), "dateTime")}
          </span>
        ) : null}
      </div>
      {card.failureCode ? (
        <p className="text-sm text-destructive">
          {t("failureCode", { code: card.failureCode })}
        </p>
      ) : null}
    </article>
  )
}

function SortableContentCard({
  card,
  column,
  index,
}: {
  card: ContentBoardCard
  column: ContentBoardColumn
  index: number
}) {
  const { isDragging, ref } = useSortable({
    id: card.id,
    index,
    type: "card",
    accept: "card",
    group: column,
    disabled: !draggableColumns.has(column),
    data: { type: "card", card },
  })

  return (
    <div className={cn("touch-none", isDragging && "opacity-30")} ref={ref}>
      <ContentCard card={card} />
    </div>
  )
}

function ContentColumn({
  cards,
  column,
}: {
  cards: readonly ContentBoardCard[]
  column: ContentBoardColumn
}) {
  const t = useTranslations("contentBoard")
  const dropTarget = useDroppable({
    id: column,
    type: "card-container",
    accept: "card",
    collisionPriority: CollisionPriority.Low,
    data: { type: "card-container", column },
  })
  const isLocked = !draggableColumns.has(column)

  return (
    <section
      className={cn(
        "flex min-h-0 flex-col rounded-t-xl border bg-muted/50 transition-colors",
        dropTarget.isDropTarget && !isLocked && "bg-muted/70"
      )}
    >
      <div className="flex items-start justify-between gap-3 px-4 pt-4 pb-3">
        <div className="min-w-0 space-y-1">
          <h2 className="flex items-center gap-1.5 truncate text-base leading-none font-medium">
            {t(`status.${column}`)}
            {isLocked ? (
              <Lock
                aria-label={t("lockedColumn")}
                className="size-3.5 text-muted-foreground"
              />
            ) : null}
          </h2>
          <p className="text-sm leading-none tabular-nums text-muted-foreground">
            {t("cardCount", { count: cards.length })}
          </p>
        </div>
      </div>
      <div
        className="scrollbar-thin flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto px-3 pb-3 [scrollbar-color:var(--border)_transparent] [&::-webkit-scrollbar]:w-1 [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-border [&::-webkit-scrollbar-track]:bg-transparent"
        ref={dropTarget.ref}
      >
        {cards.map((card, index) => (
          <SortableContentCard
            card={card}
            column={column}
            index={index}
            key={card.id}
          />
        ))}
        {cards.length ? null : (
          <p className="rounded-lg border border-dashed px-3 py-6 text-center text-sm text-muted-foreground">
            {t("emptyColumn")}
          </p>
        )}
      </div>
    </section>
  )
}

export function ContentBoardPage() {
  const t = useTranslations("contentBoard")
  const router = useRouter()
  const apiErrorMessage = useApiErrorMessage()

  const [cards, setCards] = useState<ContentBoardCard[] | null>(null)
  const [state, setState] = useState<ContentBoardState>(emptyState)
  const [isLoading, setIsLoading] = useState(true)
  const [loadFailed, setLoadFailed] = useState(false)
  const stateBeforeDrag = useRef<ContentBoardState>(emptyState())

  const load = useCallback(async () => {
    setIsLoading(true)
    setLoadFailed(false)
    try {
      const response = await boardsApi.contentBoard()
      setCards(response.cards)
      setState(groupByStatus(response.cards))
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        router.replace(loginPath())
        return
      }
      setLoadFailed(true)
      toast.error(apiErrorMessage(errorCode(error)))
    } finally {
      setIsLoading(false)
    }
  }, [apiErrorMessage, router])

  useEffect(() => {
    const timer = setTimeout(() => void load(), 0)
    return () => clearTimeout(timer)
  }, [load])

  const total = useMemo(() => cards?.length ?? 0, [cards])

  async function handleDragEnd(event: DragEndEvent) {
    const { source } = event.operation
    if (!source || source.type !== "card") return
    if (event.canceled) {
      setState(stateBeforeDrag.current)
      return
    }

    const next = move(state, event)
    setState(next)

    const cardId = String(source.id)
    const status = columnOrder.find((column) =>
      next[column].some((card) => card.id === cardId)
    )
    // Solo se envía lo que el dominio admite; el resto lo rechazaría la API de
    // todos modos, y aquí evita una petición inútil.
    if (!status || !draggableColumns.has(status)) {
      setState(stateBeforeDrag.current)
      return
    }

    try {
      const response = await boardsApi.moveContentCard(cardId, { status })
      setCards(response.cards)
      setState(groupByStatus(response.cards))
      toast.success(t("statusChanged"))
    } catch (error) {
      setState(stateBeforeDrag.current)
      toast.error(apiErrorMessage(errorCode(error)))
    }
  }

  if (isLoading && !cards) return <PageLoading />

  if (loadFailed && !cards) {
    return (
      <EmptyState
        action={<RetryButton onClick={() => void load()} />}
        description={t("loadFailedDescription")}
        icon={CircleAlert}
        title={t("loadFailed")}
      />
    )
  }

  return (
    <div
      className="flex h-[calc(100dvh-var(--dashboard-header-height))] min-h-0 min-w-0 flex-col overflow-hidden"
      data-content-padding="false"
    >
      <div className="flex shrink-0 flex-col gap-1 border-b px-4 py-3 lg:px-6">
        <h1 className="truncate text-lg font-semibold">{t("pageTitle")}</h1>
        <p className="truncate text-sm text-muted-foreground">
          {t("pageDescription", { count: total })}
        </p>
      </div>

      <DragDropProvider
        onDragEnd={(event) => void handleDragEnd(event)}
        onDragOver={(event) => setState((current) => move(current, event))}
        onDragStart={() => {
          stateBeforeDrag.current = state
        }}
      >
        <div className="scrollbar-thin min-h-0 min-w-0 flex-1 overflow-x-auto overflow-y-hidden bg-muted/25 px-4 pt-4 pb-0 [scrollbar-color:var(--border)_transparent] lg:px-5 lg:pt-5 [&::-webkit-scrollbar]:h-1 [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-border [&::-webkit-scrollbar-track]:bg-transparent">
          <div className="inline-grid h-full min-w-full grid-cols-[repeat(5,minmax(18rem,1fr))] gap-4">
            {columnOrder.map((column) => (
              <ContentColumn
                cards={state[column]}
                column={column}
                key={column}
              />
            ))}
          </div>
        </div>
      </DragDropProvider>
    </div>
  )
}

