/**
 * Conexión de cuentas de X (Twitter).
 *
 * OAuth 2.0 con PKCE obligatorio: X exige el `code_verifier` al canjear, y su
 * canje se autentica con Basic Auth del par cliente/secreto, no con los campos
 * en el cuerpo. El identificador de la cuenta sale de `/2/users/me`.
 */
@Injectable()
export class XConnectionAdapter implements ChannelConnectionAdapter {
  readonly providerKey = 'x';
  readonly usesPkce = true;

  scopesFor(_capabilityKey: PortalChannelCapabilityKey): string[] {
    // `offline.access` es lo que hace que X entregue un refresh token; sin él
    // la cuenta se desconectaría a las dos horas.
    return ['tweet.read', 'tweet.write', 'users.read', 'offline.access'];
  }

  async exchangeCode({
    clientId,
    clientSecret,
    code,
    redirectUri,
    codeVerifier,
  }: {
    clientId: string;
    clientSecret: string;
    code: string;
    redirectUri: string;
    codeVerifier?: string;
  }): Promise<{ accessToken: string; refreshToken?: string; expiresAt?: string }> {
    if (!codeVerifier) throw new ServiceUnavailableException();

    const response = await fetch('https://api.x.com/2/oauth2/token', {
      method: 'POST',
      headers: {
        'content-type': 'application/x-www-form-urlencoded',
        authorization: `Basic ${Buffer.from(`${clientId}:${clientSecret}`).toString('base64')}`,
      },
      body: new URLSearchParams({
        grant_type: 'authorization_code',
        code,
        redirect_uri: redirectUri,
        code_verifier: codeVerifier,
      }),
      signal: AbortSignal.timeout(10_000),
    });
    return this.parseToken(response);
  }

  async fetchCandidates({
    accessToken,
  }: {
    accessToken: string;
    capabilityKey: PortalChannelCapabilityKey;
  }): Promise<ConnectionCandidate[]> {
    const url = new URL('https://api.x.com/2/users/me');
    url.search = new URLSearchParams({
      'user.fields': 'profile_image_url,username,name',
    }).toString();

    const response = await fetch(url, {
      headers: { authorization: `Bearer ${accessToken}` },
      signal: AbortSignal.timeout(10_000),
    });
    const body: unknown = await response.json().catch(() => null);
    const data =
      typeof body === 'object' && body !== null
        ? (body as Record<string, unknown>).data
        : null;
    if (!response.ok || typeof data !== 'object' || data === null) {
      throw new ServiceUnavailableException();
    }
    const record = data as Record<string, unknown>;
    const id = this.text(record, 'id');
    const username = this.text(record, 'username');
    if (!id) throw new ServiceUnavailableException();

    return [
      {
        externalId: id,
        displayName: this.text(record, 'name') ?? username ?? id,
        description: 'x_profile',
        publicMetadata: {
          kind: 'x_profile',
          ...(username ? { handle: username } : {}),
        },
        context: {
          accessToken,
          avatarUrl: this.text(record, 'profile_image_url') ?? undefined,
        },
      },
    ];
  }

  private async parseToken(response: Response) {
    const body: unknown = await response.json().catch(() => null);
    const record =
      typeof body === 'object' && body !== null
        ? (body as Record<string, unknown>)
        : {};
    const accessToken = record.access_token;
    if (!response.ok || typeof accessToken !== 'string' || !accessToken) {
      throw new ServiceUnavailableException();
    }
    return {
      accessToken,
      refreshToken:
        typeof record.refresh_token === 'string'
          ? record.refresh_token
          : undefined,
      expiresAt:
        typeof record.expires_in === 'number'
          ? new Date(Date.now() + record.expires_in * 1000).toISOString()
          : undefined,
    };
  }

  private text(body: Record<string, unknown>, key: string): string | null {
    const value = body[key];
    return typeof value === 'string' && value ? value : null;
