  x: "X",
  tiktok: "TikTok",
  whatsapp: "WhatsApp",
} as const

export type MetaPickerSession = {
  capability: PortalChannelCapability
  connectionId: string
  candidates: readonly ChannelCandidate[]
}

function candidateInitials(label: string) {
  return label
    .replace(/^@/, "")
    .split(/[.\s]+/)
    .filter(Boolean)
    .map((part) => part.slice(0, 1))
    .join("")
    .slice(0, 2)
    .toUpperCase()
}

function CandidateAvatar({ candidate }: { candidate: ChannelCandidate }) {
  const t = useTranslations("channelConnection")

  return (
    <span className="relative flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-full bg-accent text-xs font-semibold text-accent-foreground">
      <span aria-hidden="true">{candidateInitials(candidate.label)}</span>
      {candidate.avatarUrl ? (
        // eslint-disable-next-line @next/next/no-img-element -- el avatar lo sirve el proveedor con un dominio que no está en `remotePatterns`.
        <img
          alt={t("avatarAlt", { name: candidate.label })}
          className="absolute inset-0 size-full object-cover"
          loading="lazy"
          onError={(event) => {
            event.currentTarget.style.display = "none"
          }}
          src={candidate.avatarUrl}
        />
      ) : null}
    </span>
  )
}

function toPortalAccount(
  account: Awaited<ReturnType<typeof channelConnectionsApi.select>>["account"]
): PortalChannelAccount {
  return {
    id: account.id,
    capabilityKey: account.capabilityKey,
    provider: account.provider,
    displayName: account.displayName,
    externalName: account.externalName,
    handle: account.handle ?? undefined,
    avatarUrl: account.avatarUrl,
    status: account.status,
    connectedAt: account.createdAt,
  }
}

export function ChannelConnectionDialog({
  capabilities,
  open,
  metaPickerSession,
  onConnected,
  onMetaAuthorizationStart,
  onMetaConnectionCompleted,
  onMetaConnectionCancelled,
  onWhatsAppConnectionCompleted,
  onOpenChange,
  whatsappReconnectAccountId,
}: {
  capabilities: readonly PortalChannelCapability[]
  open: boolean
  metaPickerSession: MetaPickerSession | null
  onConnected: (account: PortalChannelAccount) => void
  onMetaAuthorizationStart: (
    result: Awaited<ReturnType<typeof channelConnectionsApi.startMeta>>,
    capability: PortalChannelCapability
  ) => void
  onMetaConnectionCompleted: () => Promise<void>
  onMetaConnectionCancelled: () => void
  onWhatsAppConnectionCompleted: () => Promise<void>
  onOpenChange: (open: boolean) => void
  whatsappReconnectAccountId: string | null
}) {
  const t = useTranslations("channelConnection")
  const labels = useChannelLabels()
  const [capability, setCapability] = useState<PortalChannelCapability | null>(
    null
  )
  const [candidate, setCandidate] = useState<ChannelCandidate | null>(null)
  const [step, setStep] = useState<DialogStep>("capabilities")
  const [isAuthorizing, setIsAuthorizing] = useState(false)
  const [isSelecting, setIsSelecting] = useState(false)

  const entrada = !open
    ? null
    : metaPickerSession
      ? `picker:${metaPickerSession.capability.key}`
      : whatsappReconnectAccountId
        ? `whatsapp:${whatsappReconnectAccountId}`
        : null
  const [ultimaEntrada, setUltimaEntrada] = useState(entrada)

  if (entrada !== ultimaEntrada) {
    setUltimaEntrada(entrada)
    if (metaPickerSession && open) {
      setCapability(metaPickerSession.capability)
      setCandidate(null)
      setStep("picker")
    } else if (whatsappReconnectAccountId && open) {
      const whatsappCapability = capabilities.find(
        (item) => item.key === "whatsapp_status"
      )
      if (whatsappCapability) {
        setCapability(whatsappCapability)
        setCandidate(null)
        setStep("whatsapp")
      }
    }
  }

  function reset() {
    setCapability(null)
    setCandidate(null)
    setStep("capabilities")
    setIsAuthorizing(false)
    setIsSelecting(false)
  }

  const [wasOpen, setWasOpen] = useState(open)

  if (open !== wasOpen) {
    setWasOpen(open)
    if (!open) reset()
  }

  function handleOpenChange(nextOpen: boolean) {
    if (!nextOpen) reset()
    onOpenChange(nextOpen)
  }

  async function selectCapability(nextCapability: PortalChannelCapability) {
    setCapability(nextCapability)
    setCandidate(null)

    if (nextCapability.connectionKind === "qr_device") {
      setStep("whatsapp")
      return
    }

    setIsAuthorizing(true)
    try {
      const result = await channelConnectionsApi.startMeta({
        capabilityKey: nextCapability.key,
      })
      onMetaAuthorizationStart(result, nextCapability)
    } catch (error) {
      console.error("Channel authorization start failed", error)
      toast.error(t("authStartFailed"))
      setStep("capabilities")
    } finally {
      setIsAuthorizing(false)
    }
  }

  function finishMockConnection(selected: ChannelCandidate) {
    if (!capability || capability.provider === "meta") return
    onConnected({
      id: `mock-${capability.key}-${selected.id}`,
      capabilityKey: capability.key,
      provider: capability.provider,
      displayName: selected.label,
      handle: selected.label.startsWith("@")
        ? selected.label.slice(1)
        : undefined,
      status: "connected",
      connectedAt: "2026-07-31",
    })
    setStep("connected")
    toast.success(
      t("mockConnected", { channel: labels.capability(capability.key) })
    )
  }

  function authorizeMock() {
    if (!capability || capability.provider === "meta") return
    if (capability.connectionKind === "picker") {
      setStep("picker")
      return
    }
    finishMockConnection({
      id: `${capability.key}-direct`,
      label: t("accountOf", { provider: providerLabels[capability.provider] }),
      description: labels.capability(capability.key),
    })
  }

  async function selectMetaCandidate() {
    if (!candidate || !metaPickerSession) return
    setIsSelecting(true)
    try {
      const result = await channelConnectionsApi.select(
        metaPickerSession.connectionId,
        {
          candidateId: candidate.id,
        }
      )
      onConnected(toPortalAccount(result.account))
      await onMetaConnectionCompleted()
      toast.success(
        t("connected", {
          channel: labels.capability(metaPickerSession.capability.key),
        })
      )
    } catch (error) {
      console.error("Meta candidate selection failed", error)
      toast.error(t("connectFailed"))
    } finally {
      setIsSelecting(false)
    }
  }

  async function cancelPicker() {
    if (capability?.provider === "meta") {
      if (!metaPickerSession) return
      setIsSelecting(true)
      try {
        await channelConnectionsApi.cancel(metaPickerSession.connectionId)
        onMetaConnectionCancelled()
        reset()
        onOpenChange(false)
        toast.success(t("cancelled"))
      } catch (error) {
        console.error("Meta connection cancellation failed", error)
        toast.error(t("cancelFailed"))
      } finally {
        setIsSelecting(false)
      }
      return
    }

    reset()
    onOpenChange(false)
  }

  function submitCandidate(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (!candidate || !capability) {
      toast.error(t("pickAccount"))
      return
    }

    if (capability.provider === "meta") {
      if (!metaPickerSession) {
        toast.error(t("sessionLost"))
        return
      }
      void selectMetaCandidate()
      return
    }

    finishMockConnection(candidate)
  }

  const title = capability
    ? t("connectChannel", { channel: labels.capability(capability.key) })
    : t("connectAnyChannel")
  const isMetaPicker = capability?.provider === "meta"
  const pickerCandidates = isMetaPicker
    ? (metaPickerSession?.candidates ?? [])
    : (capability?.candidates ?? [])

  return (
    <Sheet onOpenChange={handleOpenChange} open={open}>
      <SheetContent
        className="w-full gap-0 p-0 sm:max-w-none data-[side=right]:sm:w-full data-[side=right]:sm:border-l-0"
        side="right"
      >
        <SheetHeader className="border-b">
          <SheetTitle>{title}</SheetTitle>
          <SheetDescription>
            {capability?.provider === "meta"
              ? t("metaDescription")
              : t("otherProviderDescription")}
          </SheetDescription>
        </SheetHeader>
        <div className="flex min-h-0 flex-1 flex-col overflow-y-auto p-4">
          <div className="mx-auto grid w-full max-w-5xl gap-4">
            {step === "capabilities" ? (
              <ChannelCapabilityGrid
                capabilities={capabilities}
                onSelect={(capability) => void selectCapability(capability)}
              />
            ) : null}

            {isAuthorizing ? (
              <Card variant="inset">
                <CardContent className="flex items-center gap-3 py-5 text-sm text-muted-foreground">
                  <Spinner aria-label={t("preparingAria")} />
                  {t("preparing")}
                </CardContent>
              </Card>
            ) : null}

            {step === "authorizing" && capability ? (
              <div className="grid gap-5">
                <Card variant="inset">
                  <CardContent className="flex items-start gap-3 py-5">
                    <ShieldCheck
                      aria-hidden="true"
                      className="mt-0.5 size-5 text-primary"
                    />
                    <div className="grid gap-1">
                      <p className="font-medium">
                        {t("mockAuthorization", {
                          provider: providerLabels[capability.provider],
                        })}
                      </p>
                      <p className="text-sm leading-relaxed text-muted-foreground">
                        {t("mockAuthorizationHint")}
                      </p>
                    </div>
                  </CardContent>
                </Card>
                <div className="flex justify-end">
                  <Button onClick={authorizeMock} type="button">
                    <ShieldCheck data-icon="inline-start" />
                    {t("simulateAuth")}
                  </Button>
                </div>
              </div>
            ) : null}

            {step === "picker" && capability ? (
              <form
                aria-busy={isSelecting}
                className="grid gap-4"
                noValidate
                onSubmit={submitCandidate}
              >
                <Field>
                  <FieldLabel id="channel-candidate-label">
                    {t("availableAccount")}
                    <span aria-hidden="true" className="text-destructive">
                      *
                    </span>
                  </FieldLabel>
                  <CardGrid
                    aria-labelledby="channel-candidate-label"
                    aria-required="true"
                    layout="xl-3"
                    role="radiogroup"
                  >
                    {pickerCandidates.map((item) => (
                      <Button
                        aria-checked={candidate?.id === item.id}
                        className="h-auto justify-start gap-3 px-4 py-3 text-left whitespace-normal"
                        disabled={isSelecting}
                        key={item.id}
                        onClick={() => setCandidate(item)}
                        role="radio"
                        type="button"
                        variant={
                          candidate?.id === item.id
                            ? "brand-secondary"
                            : "surface"
                        }
                      >
                        <CandidateAvatar candidate={item} />
                        <span className="grid min-w-0 gap-0.5">
                          <span>{item.label}</span>
                          <span className="text-sm font-normal text-muted-foreground">
                            {item.description}
                          </span>
                          {item.metadata ? (
                            <span className="text-xs font-normal text-muted-foreground">
                              {item.metadata}
                            </span>
                          ) : null}
                        </span>
                      </Button>
                    ))}
                  </CardGrid>
                </Field>
                <div className="flex justify-end gap-2">
                  <Button
                    disabled={isSelecting}
                    onClick={() => void cancelPicker()}
                    type="button"
                    variant="brand-secondary"
                  >
                    {t("cancel")}
                  </Button>
                  <Button disabled={!candidate || isSelecting} type="submit">
                    {isSelecting ? (
                      <Spinner
                        aria-label={t("connecting")}
                        data-icon="inline-start"
                      />
                    ) : (
                      <CheckCircle2 data-icon="inline-start" />
                    )}
                    {t("connectSelection")}
                  </Button>
                </div>
              </form>
            ) : null}

            {step === "whatsapp" ? (
              <WhatsAppStatusConnection
                reconnectAccountId={whatsappReconnectAccountId ?? undefined}
                onConnected={async (account) => {
                  onConnected(account)
                  await onWhatsAppConnectionCompleted()
                  reset()
                  onOpenChange(false)
                }}
              />
            ) : null}

            {step === "connected" && capability ? (
              <Card variant="inset">
                <CardContent className="flex items-start gap-3 py-5">
                  <CheckCircle2
                    aria-hidden="true"
                    className="mt-0.5 size-5 text-success"
                  />
                  <div className="grid gap-1">
                    <p className="font-medium">
                      {t("connected", {
                        channel: labels.capability(capability.key),
                      })}
                    </p>
                    <p className="text-sm text-muted-foreground">
                      {t("connectedHint")}
                    </p>
                  </div>
                </CardContent>
              </Card>
            ) : null}
          </div>
        </div>
      </SheetContent>
    </Sheet>
  )
}

  if (handledOAuthOutcome.current === outcome) return
  handledOAuthOutcome.current = outcome
  clearMetaOAuthReturnUrl()

  if (outcome === "denied" || outcome === "failed") {
    window.sessionStorage.removeItem(META_OAUTH_SESSION_KEY)
    toast.error(outcome === "denied" ? t("metaCancelled") : t("metaFailed"))
    return
  }

  if (outcome !== "authorized") {
    window.sessionStorage.removeItem(META_OAUTH_SESSION_KEY)
    toast.error(t("metaFailed"))
    return
  }

  if (searchParams.get("provider") !== "meta") {
    window.sessionStorage.removeItem(META_OAUTH_SESSION_KEY)
    toast.success(t("channelConnected"))
    void loadChannels()
    return
  }

  const session = readMetaOAuthSession()
  if (!session) {
    return
  }

  void (async () => {
    try {
      const response = await channelConnectionsApi.candidates(
        session.connectionId
      )
      const capability =
        capabilities.find((item) => item.key === session.capabilityKey) ??
        metaOAuthPickerCapability(session.capabilityKey)
      if (!capability || capability.provider !== "meta")
        throw new Error("Missing Meta capability")
      setMetaPickerSession({
        capability,
        connectionId: response.connectionId,
        candidates: response.candidates.map((candidate) => ({
          ...candidate,
          avatarUrl: candidate.avatarUrl ?? null,
          metadata: candidate.metadata ?? undefined,
        })),
      })
      setIsConnectOpen(true)
    } catch (error) {
      window.sessionStorage.removeItem(META_OAUTH_SESSION_KEY)
      console.error("Meta candidates request failed", error)
      toast.error(t("metaAccountsFailed"))
    }
  })()
}, [capabilities, router, searchParams, t])

function addAccount(account: PortalChannelAccount) {
  setAccounts((current) => [
    ...current.filter((item) => item.id !== account.id),
    account,
  ])
}

function beginMetaAuthorization(
  result: Awaited<ReturnType<typeof channelConnectionsApi.startMeta>>,
  capability: PortalChannelCapability
) {
  window.sessionStorage.setItem(
    META_OAUTH_SESSION_KEY,
    JSON.stringify({
      connectionId: result.connection.id,
      capabilityKey: capability.key,
    } satisfies MetaOAuthSession)
  )
  window.location.assign(result.authorizationUrl)
}

async function reconnect(account: PortalChannelAccount) {
  if (account.capabilityKey === "whatsapp_status") {
    setWhatsappReconnectAccountId(account.id)
    setIsConnectOpen(true)
    return
  }

  setPendingAccountId(account.id)
  try {
    const result = await channelsApi.reconnect(account.id)
    const capability = metaOAuthPickerCapability(account.capabilityKey)
    if (!capability) throw new Error("Missing Meta capability")
    beginMetaAuthorization(result, capability)
  } catch (error) {
    console.error("Channel reconnect failed", error)
    toast.error(t("reconnectFailed"))
    setPendingAccountId(null)
  }
}

async function refreshProfile(account: PortalChannelAccount) {
  setPendingAccountId(account.id)
  try {
    await channelsApi.requestProfileSync(account.id)
    toast.success(t("profileSyncQueued"))
  } catch (error) {
    if (
      error instanceof ApiError &&
      error.code === "CHANNEL_PROFILE_SYNC_COOLDOWN"
    ) {
      toast.error(t("profileSyncCooldown"))
    } else {
      console.error("Channel profile sync request failed", error)
      toast.error(t("profileSyncFailed"))
    }
  } finally {
    setPendingAccountId(null)
  }
}

async function renameAccount(displayName: string) {
  if (!editingAccount) return
  setPendingAccountId(editingAccount.id)
  try {
    const updated = await channelsApi.update(editingAccount.id, {
      displayName,
    })
    addAccount(toPortalAccount(updated))
    setEditingAccount(null)
    toast.success(t("nameUpdated"))
  } catch (error) {
    console.error("Channel update failed", error)
    toast.error(t("updateFailed"))
  } finally {
    setPendingAccountId(null)
  }
}

async function confirmDelete() {
  if (!deletingAccount) return
  setPendingAccountId(deletingAccount.id)
  try {
    await channelsApi.remove(deletingAccount.id)
    setDeletingAccount(null)
    toast.success(t("deleted"))
    await loadChannels()
  } catch (error) {
    console.error("Channel delete failed", error)
    toast.error(t("deleteFailed"))
  } finally {
    setPendingAccountId(null)
  }
}

async function completeMetaConnection() {
  await loadChannels()
  window.sessionStorage.removeItem(META_OAUTH_SESSION_KEY)
  setMetaPickerSession(null)
  setIsConnectOpen(false)
}

function cancelMetaConnection() {
  window.sessionStorage.removeItem(META_OAUTH_SESSION_KEY)
  setMetaPickerSession(null)
}

