        ownerName: row.ownerName,
        ownerEmail: row.ownerEmail,
        planName: row.planName,
        memberCount: row.memberCount,
        accountCount: row.accountCount,
        createdAt: row.createdAt.toISOString(),
      })),
      total: summary.total,
    };
  }
}
