"use client"

import { useCallback, useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { useFormatter, useTranslations } from "next-intl"
import {
  BadgeCheck,
  CircleAlert,
  MailCheck,
  ShieldX,
  TrendingUp,
  UserPlus,
  Users,
} from "lucide-react"

import { ApiError, adminReportsApi } from "@workspace/api-client"
import type { AdminUserReportResponse } from "@workspace/contracts"
import { Badge } from "@workspace/ui/components/badge"
import { Card, CardContent, CardHeader, CardTitle } from "@workspace/ui/components/card"
import { CardGrid } from "@workspace/ui/components/card-grid"
import { CollectionHeader } from "@workspace/ui/components/collection-header"
import { EmptyState } from "@workspace/ui/components/empty-state"
import { MetricCard } from "@workspace/ui/components/metric-card"
import { RetryButton } from "@workspace/ui/components/retry-button"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@workspace/ui/components/table"
import { toast } from "@workspace/ui/components/toast"
import { PageLoading } from "@/components/page-loading"
import { useApiErrorMessage } from "@/lib/api-error-message"
import { loginPath } from "@/features/identity/login-redirect"

function errorCode(error: unknown) {
  return error instanceof ApiError ? error.code : undefined
}

export function AdminUserReportPage() {
  const t = useTranslations("adminUserReport")
  const format = useFormatter()
  const router = useRouter()
  const apiErrorMessage = useApiErrorMessage()

  const [data, setData] = useState<AdminUserReportResponse | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [loadFailed, setLoadFailed] = useState(false)
  const [forbidden, setForbidden] = useState(false)

  const load = useCallback(async () => {
    setLoadFailed(false)
    try {
      setData(await adminReportsApi.userReport())
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        router.replace(loginPath())
        return
      }
      if (error instanceof ApiError && error.status === 403) {
        setForbidden(true)
        return
      }
      setLoadFailed(true)
      toast.error(apiErrorMessage(errorCode(error)))
    } finally {
      setIsLoading(false)
    }
  }, [apiErrorMessage, router])

  useEffect(() => {
    const timer = setTimeout(() => void load(), 0)
    return () => clearTimeout(timer)
  }, [load])

  if (forbidden) {
    return (
      <EmptyState
        description={t("forbiddenDescription")}
        icon={ShieldX}
        title={t("forbiddenTitle")}
      />
    )
  }

  if (isLoading && !data) return <PageLoading aria-label={t("loading")} />

  if (loadFailed || !data) {
    return (
      <EmptyState
        action={<RetryButton onClick={() => void load()} />}
        description={t("loadFailedDescription")}
        icon={CircleAlert}
        title={t("loadFailedTitle")}
      />
    )
  }

  return (
    <div className="flex flex-col gap-4">
      <CollectionHeader
        description={t("pageDescription")}
        title={t("pageTitle")}
      />
      <CardGrid layout="xl-4">
        <MetricCard
          icon={Users}
          label={t("totalUsers")}
          value={format.number(data.totals.users)}
        />
        <MetricCard
          icon={UserPlus}
          label={t("newUsers")}
          value={format.number(data.totals.newLast30Days)}
        />
        <MetricCard
          icon={TrendingUp}
          label={t("growth")}
          value={t("growthValue", { value: data.totals.growthPct })}
        />
        <MetricCard
          icon={MailCheck}
          label={t("verified")}
          value={t("percentValue", { value: data.totals.verifiedPct })}
        />
      </CardGrid>
      <div className="grid gap-4 lg:grid-cols-2">
        <Card variant="subtle">
          <CardHeader>
            <CardTitle>{t("byMonth")}</CardTitle>
          </CardHeader>
          <CardContent>
            <ul className="grid gap-1.5">
              {data.signupsByMonth.map((entry) => (
                <li
                  className="flex items-center justify-between gap-3 text-sm"
                  key={entry.month}
                >
                  <span className="text-muted-foreground">{entry.month}</span>
                  <span className="tabular-nums">
                    {format.number(entry.count)}
                  </span>
                </li>
              ))}
              {data.signupsByMonth.length ? null : (
                <li className="text-sm text-muted-foreground">
                  {t("noData")}
                </li>
              )}
            </ul>
          </CardContent>
        </Card>
        <div className="grid gap-4">
          <Card variant="subtle">
            <CardHeader>
              <CardTitle>{t("byLocale")}</CardTitle>
            </CardHeader>
            <CardContent>
              <ul className="grid gap-1.5">
                {data.byLocale.map((entry) => (
                  <li
                    className="flex items-center justify-between gap-3 text-sm"
                    key={entry.locale}
                  >
                    <span className="text-muted-foreground">
                      {entry.locale}
                    </span>
                    <span className="tabular-nums">
                      {format.number(entry.count)}
                    </span>
                  </li>
                ))}
                {data.byLocale.length ? null : (
                  <li className="text-sm text-muted-foreground">
                    {t("noData")}
                  </li>
                )}
              </ul>
            </CardContent>
          </Card>
          <Card variant="subtle">
            <CardHeader>
              <CardTitle>{t("byPlan")}</CardTitle>
            </CardHeader>
            <CardContent>
              <ul className="grid gap-1.5">
                {data.workspacesByPlan.map((entry) => (
                  <li
                    className="flex items-center justify-between gap-3 text-sm"
                    key={entry.plan}
                  >
                    <span className="text-muted-foreground">{entry.plan}</span>
                    <span className="tabular-nums">
                      {format.number(entry.count)}
                    </span>
                  </li>
                ))}
                {data.workspacesByPlan.length ? null : (
                  <li className="text-sm text-muted-foreground">
                    {t("noData")}
                  </li>
                )}
              </ul>
            </CardContent>
          </Card>
        </div>
      </div>
      <Card variant="subtle">
        <CardHeader>
          <CardTitle>{t("recentTitle")}</CardTitle>
        </CardHeader>
        <CardContent className="px-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>{t("userColumn")}</TableHead>
                <TableHead className="max-md:hidden">
                  {t("planColumn")}
                </TableHead>
                <TableHead>{t("statusColumn")}</TableHead>
                <TableHead className="max-lg:hidden">
                  {t("signupColumn")}
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {data.recent.map((user) => (
                <TableRow key={user.id}>
                  <TableCell>
                    <div className="grid gap-0.5">
                      <span className="font-medium">{user.displayName}</span>
                      <span className="text-sm text-muted-foreground">
                        {user.email}
                        {user.locale ? ` · ${user.locale}` : ""}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell className="max-md:hidden">
                    {user.planName ?? t("noPlan")}
                  </TableCell>
                  <TableCell>
                    {user.verified ? (
                      <Badge variant="success">
                        <BadgeCheck data-icon="inline-start" />
                        {t("verifiedBadge")}
                      </Badge>
                    ) : (
                      <Badge variant="neutral">{t("unverifiedBadge")}</Badge>
                    )}
                  </TableCell>
                  <TableCell className="max-lg:hidden">
                    {format.dateTime(new Date(user.createdAt), "date")}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { useCallback, useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { useFormatter, useTranslations } from "next-intl"
import {
  Cable,
  CircleAlert,
  ShieldX,
  Users,
  UsersRound,
} from "lucide-react"

import { ApiError, adminReportsApi } from "@workspace/api-client"
import type { AdminTeamsResponse } from "@workspace/contracts"
import { Badge } from "@workspace/ui/components/badge"
import { Card, CardContent } from "@workspace/ui/components/card"
import { CardGrid } from "@workspace/ui/components/card-grid"
import { CollectionHeader } from "@workspace/ui/components/collection-header"
import { DataTableHeader } from "@workspace/ui/components/data-table-controls"
import { EmptyState } from "@workspace/ui/components/empty-state"
import { MetricCard } from "@workspace/ui/components/metric-card"
import { RetryButton } from "@workspace/ui/components/retry-button"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@workspace/ui/components/table"
import { TablePagination } from "@/components/table-pagination"
import { toast } from "@workspace/ui/components/toast"
import { PageLoading } from "@/components/page-loading"
import { useApiErrorMessage } from "@/lib/api-error-message"
import { loginPath } from "@/features/identity/login-redirect"

const pageSize = 25

function errorCode(error: unknown) {
  return error instanceof ApiError ? error.code : undefined
}

export function AdminTeamsPage() {
  const t = useTranslations("adminTeams")
  const format = useFormatter()
  const router = useRouter()
  const apiErrorMessage = useApiErrorMessage()

  const [data, setData] = useState<AdminTeamsResponse | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [loadFailed, setLoadFailed] = useState(false)
  const [forbidden, setForbidden] = useState(false)
  const [query, setQuery] = useState("")
  const [page, setPage] = useState(1)

  const load = useCallback(async () => {
    setLoadFailed(false)
    try {
      setData(
        await adminReportsApi.teams({
          q: query.trim() || undefined,
          offset: (page - 1) * pageSize,
          limit: pageSize,
        })
      )
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        router.replace(loginPath())
        return
      }
      if (error instanceof ApiError && error.status === 403) {
        setForbidden(true)
        return
      }
      setLoadFailed(true)
      toast.error(apiErrorMessage(errorCode(error)))
    } finally {
      setIsLoading(false)
    }
  }, [apiErrorMessage, page, query, router])

  useEffect(() => {
    const timer = setTimeout(() => void load(), query ? 300 : 0)
    return () => clearTimeout(timer)
  }, [load, query])

  if (forbidden) {
    return (
      <EmptyState
        description={t("forbiddenDescription")}
        icon={ShieldX}
        title={t("forbiddenTitle")}
      />
    )
  }

  if (isLoading && !data) return <PageLoading aria-label={t("loading")} />

  if (loadFailed && !data) {
    return (
      <EmptyState
        action={<RetryButton onClick={() => void load()} />}
        description={t("loadFailedDescription")}
        icon={CircleAlert}
        title={t("loadFailedTitle")}
      />
    )
  }

  const teams = data?.teams ?? []
  const total = data?.total ?? 0
  const pageCount = Math.max(1, Math.ceil(total / pageSize))
  const safePage = Math.min(page, pageCount)
  const rangeStart = total ? (safePage - 1) * pageSize + 1 : 0
  const rangeEnd = total
    ? Math.min(rangeStart + teams.length - 1, total)
    : 0

  return (
    <div className="flex flex-col gap-4">
      <CollectionHeader
        description={t("pageDescription")}
        title={t("pageTitle")}
      />
      <CardGrid layout="xl-4">
        <MetricCard
          icon={UsersRound}
          label={t("totalWorkspaces")}
          value={format.number(data?.totals.workspaces ?? 0)}
        />
        <MetricCard
          icon={Users}
          label={t("teamWorkspaces")}
          value={format.number(data?.totals.teamWorkspaces ?? 0)}
        />
        <MetricCard
          icon={Users}
          label={t("averageMembers")}
          value={format.number(data?.totals.averageMembers ?? 0)}
        />
        <MetricCard
          icon={Cable}
          label={t("connectedAccounts")}
          value={format.number(data?.totals.connectedAccounts ?? 0)}
        />
      </CardGrid>
      <Card variant="subtle">
        <DataTableHeader
          search={{
            ariaLabel: t("searchLabel"),
            onChange: (value) => {
              setQuery(value)
              setPage(1)
            },
            placeholder: t("searchPlaceholder"),
            value: query,
          }}
        />
        <CardContent className="flex flex-col gap-4 px-0">
          {teams.length ? (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>{t("teamColumn")}</TableHead>
                  <TableHead>{t("ownerColumn")}</TableHead>
                  <TableHead className="max-md:hidden">
                    {t("planColumn")}
                  </TableHead>
                  <TableHead className="max-lg:hidden">
                    {t("membersColumn")}
                  </TableHead>
                  <TableHead className="max-lg:hidden">
                    {t("accountsColumn")}
                  </TableHead>
                  <TableHead className="max-xl:hidden">
                    {t("createdColumn")}
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {teams.map((team) => (
                  <TableRow key={team.id}>
                    <TableCell>
                      <div className="grid gap-0.5">
                        <span className="flex items-center gap-2 font-medium">
                          {team.name}
                          {team.kind === "personal" ? (
                            <Badge variant="neutral">{t("personal")}</Badge>
                          ) : null}
                        </span>
                        <span className="font-mono text-xs text-muted-foreground">
                          {team.slug}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="grid gap-0.5">
                        <span className="text-sm">{team.ownerName}</span>
                        <span className="text-xs text-muted-foreground">
                          {team.ownerEmail}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell className="max-md:hidden">
                      {team.planName ?? t("noPlan")}
                    </TableCell>
                    <TableCell className="max-lg:hidden tabular-nums">
                      {format.number(team.memberCount)}
                    </TableCell>
                    <TableCell className="max-lg:hidden tabular-nums">
                      {format.number(team.accountCount)}
                    </TableCell>
                    <TableCell className="max-xl:hidden">
                      {format.dateTime(new Date(team.createdAt), "date")}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          ) : (
            <div className="px-6">
              <EmptyState
                description={t("emptyDescription")}
                icon={UsersRound}
                title={t("emptyTitle")}
              />
            </div>
          )}
          <TablePagination
            canGoNext={safePage < pageCount}
            canGoPrevious={safePage > 1}
            itemLabel={t("itemLabel")}
            onNextPage={() => setPage((current) => current + 1)}
            onPreviousPage={() => setPage((current) => current - 1)}
            rangeEnd={rangeEnd}
            rangeStart={rangeStart}
            total={total}
          />
        </CardContent>
      </Card>
    </div>
  )
}

